    [2605] = {
      [1] = {
        extrastory_title = "A Colorful Day",
        beijing = "Bg/3890.png",
        sentence = [[
Early on a weekend morning, the boy was already up.

He followed the routine as promised: eating two slices of bread and drinking a carton of milk, then taking a seat on the staircase facing the front door with a book. However, today, the words that often captivated him couldn't hold his attention. His eyes repeatedly flicked toward the door, anticipating something important.

Today was the day his parents were supposed to return home.]],
        music = "48_Quiet_Daily"
      },
      [2] = {
        extrastory_title = "A Colorful Day",
        beijing = "Bg/3890.png",
        sentence = "The usually quiet house seemed even more silent over the past few days. He could hear the book pages flipping, the clock ticking forward, and the dripping water from the washing machine—all sounds were present except for the voices of his mom and dad. The boy touched his chest, a strange pressure building there, making him distinctly uncomfortable. He had experienced this before, but it was never this intense.\n\nWas he sick?",
        music = "48_Quiet_Daily"
      },
      [3] = {
        extrastory_title = "A Colorful Day",
        beijing = "Bg/3890.png",
        sentence = [[
He wasn't sure, and he felt he hadn't quite managed to fulfill the promise of acting like an adult in his parents' absence. Tears welled up as he felt a growing discomfort in his chest. He tried to soothe himself and rubbed his eyes.

He resolved to confess to his parents about the failed experiment and his sickness, remembering how a previous sudden fever had made them worried for quite some days.

Hugging his thick book, he sat silently with his head lowered. But suddenly, rapid footsteps approached from outside, mixed with the soft jingle of keys and muffled conversations. As sunlight began to stream through the widening door crack, the boy straightened up, his eyes widening at the sight of his parents' familiar figures stepping through the doorway.]],
        music = "48_Quiet_Daily"
      },
      [4] = {
        extrastory_title = "A Colorful Day",
        beijing = "Bg/3890.png",
        sentence = [[
It felt as if something within him was set in motion, compelling him to stand and rush toward them.

"Where's my big boy? Daddy's home!"

"Let's see if you've been eating well when we were gone."

Wrapped in his parents' embrace, the tightness in his chest eased, and the pain dissipated. It felt odd; he could vividly feel and picture their presence when he was alone in the house, but now that they were here...

It was a completely different sensation.]],
        music = "48_Quiet_Daily"
      },
      [5] = {
        extrastory_title = "A Colorful Day",
        beijing = "Bg/3890.png",
        sentence = "He gripped his dad's shirt tightly, and after a moment, he gathered the courage to apologize. \"Mom, Dad, I'm sorry, I didn't really manage to act like an adult, and I think I might be a little sick…\" Upon those words, his parents immediately changed their expressions and kneeled down to inquire more carefully. \"It hurts here, and...\" Unable to meet their eyes, he spoke with his head hung low.\n\nAfter he explained everything, the room fell silent, his eyes warming up with tears again. But then, a laugh broke through the tension, filled with a touch of resignation. He looked up to see them both smiling, his mother's eyes slightly teary as she pulled him into a tighter embrace.",
        music = "48_Quiet_Daily"
      },
      [6] = {
        extrastory_title = "A Colorful Day",
        beijing = "Bg/3890.png",
        sentence = [[
"Don't worry, honey. I know what this 'illness' is because I've had it too."

"Really? Are you okay now, Mom?"

"Of course. This 'illness' can be cured."

The boy was puzzled by his mother's words, but he felt comforted as she continued, "This 'illness' is called 'missing someone.' It goes away as soon as you see the person you've been missing."

"Strictly speaking, it's not really an illness at all," her eyes warm as she gently stroked his cheek. "You're not sick; you just missed us, just like we missed you."]],
        music = "48_Quiet_Daily"
      },
      [7] = {
        extrastory_title = "A Colorful Day",
        beijing = "Bg/3890.png",
        sentence = "\"I... missed you.\"\n\nThe boy blinked his eyes, realizing the answer. He had simply missed them.\n\nHis smile broadened as the warmth of the sun seemed to wrap him in a soft embrace. At that moment, his dad took out a small bag and handed it to him with a proud look, \"Look what Daddy's got for you?\"\n\nHe opened the bag cautiously, feeling a soft, fuzzy texture brush against his fingertips—a fluffy little fox backpack. \"We've always bought you books. This time, I thought I'd try something new.\"",
        music = "48_Quiet_Daily"
      },
      [8] = {
        extrastory_title = "A Colorful Day",
        beijing = "Bg/3890.png",
        sentence = "\"When we go out for some family activities next time, you can wear it on your back and be the coolest little boy on the block.\"\n\nThough he couldn't fully agree with his father, the boy slung the small backpack over his shoulders. It was so petite that it couldn't even fit the smallest book he read—he frowned slightly but quickly hid it away.\n\nHis mom then retrieved a bag from her suitcase, pulling out a set of purple clothes with a white shirt featuring a tiny rainbow in the center.\n\n\"This will go really well with your new little fox backpack.\"",
        music = "48_Quiet_Daily"
      },
      [9] = {
        extrastory_title = "A Colorful Day",
        beijing = "Bg/3890.png",
        sentence = [[
"Wow, are your students aware that their professor is such a terrible liar?"

They all laughed happily as the little boy put on his new clothes and stood in the sunlight.

"I checked the weather forecast, and it's going to be beautiful tomorrow. How about we go for a picnic in the park?"

"Sure! Then I'll phone in the office and let them know."

The boy gazed at the rainbow on his chest, its colors glistening under the warm sun, casting radiant hues.]],
        music = "48_Quiet_Daily"
      }
    }
