    [2705] = {
      [1] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = [[
By day ten of the tour, the children from different classes had become friends. Even while waiting for the bus, they ran around, playing and laughing together. At their age, with plenty of energy to burn, the teachers and parents allowed them to enjoy themselves, as long as it was safe.

Among the lively children, one quiet boy stood out. He stood straight and calm, his neatly pressed shirt only adding to his mature, composed demeanor. He stayed close to his mother, showing no impatience despite the bus's delay.]],
        music = "60_Beaytiful_Daily"
      },
      [2] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = "\"Hey, Victor, do you want to come play with Colin and the others?'\n\nA parent called out with a smile.\n\nThe boy's mother patted his head at the words, \"Go on, Victor. I'll call you when the bus arrives.\"\n\nVictor shook his head, offering no explanation for his refusal.\n\nThe friendly parent walked over and started chatting with Victor's mother.\n\n\"Your Victor is so well-behaved, unlike my little troublemaker—it's like he wants to blow a hole through the roof or something...\"",
        music = "60_Beaytiful_Daily"
      },
      [3] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = "Victor's mother laughed, pride shining in her eyes as she looked at her son. Yet, there was something else there too—perhaps a touch of regret or guilt, \"He's always been such a good boy, ever since he was little. I've never had to worry about him.\"\n\n\"I'd let him hang out more with the other kids if I were you, though. It helps them fit in as they grow up. Being too reserved can be a problem, and we parents won't always be around.\"\n\nVictor's mother smiled but remained silent, her gaze lowering slightly as if lost in thought. Victor glanced up at her, noticing the silence of his mother. After a moment, he suddenly spoke.\n\n\"Mom, I want to go play with my classmates.\"",
        music = "60_Beaytiful_Daily"
      },
      [4] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = "His mother was surprised but quickly smiled, gently tapping his nose. \"Go on, then.\"\n\nShe watched as he quickly joined the other children, her smile growing as small dimples appeared on her cheeks.\n\n\"He's... not actually shy.\"\n\"He's just very mature for his age, always having a mind of his own.\"\n\nTen minutes later, the bus finally arrived, fashionably late.\n\nThe day's schedule was light—after visiting an art university in the morning, they were headed for a restaurant booked by the school for lunch.",
        music = "60_Beaytiful_Daily"
      },
      [5] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = "The family-style restaurant was brightly lit and decorated with care, with colorful balloons and ribbons adorning every corner. The children excitedly ran around the restaurant until the teacher asked them to take their seats.\n\n\"While we wait for lunch, we've prepared a little art trivia quiz! And there are prizes! Let's reveal what they are now—the third prize is...\"\n\nThe children buzzed with excitement, eagerly raising their hands to participate.\n\nBut Victor, still calm and composed, showed little interest. He was hungry and only wanted lunch to arrive as soon as possible.\n\n\"And now for the grand prize—the winner will receive tickets to a performance by the famous French symphony orchestra!\"",
        music = "60_Beaytiful_Daily"
      },
      [6] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = [[
"Wow! I thought they were all sold out." Victor's mother gasped softly.

Victor noticed the excitement in her eyes. After thinking for a moment, he raised his hand. "I want to participate too."

The quiz ended quickly. All the questions were based on things the teacher had covered during the tour, so Victor found them easy.

The teacher placed a beautiful garland on his head and handed him a small crown with the word "No.1" written on it. Victor thanked the teacher politely, accepted the two concert tickets, and returned to his seat. But instead of being overjoyed by the tickets, his mother seemed even more proud of his performance. She opened her arms and gave him a big hug.]],
        music = "60_Beaytiful_Daily"
      },
      [7] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = "\"That's my boy!\"\n\nWith his chin resting on his mother's shoulder, Victor glanced at the concert tickets in his hand. His usual serious expression softened, a small hint of joy creeping through.\n\nHe joined the quiz to win the tickets for his mother, hoping to make her happy. But he somehow forgot that his mother always smiled—when he did well, when he debated things with his father, when he achieved good grades. And most of the time, it seemed that when he smiled, she smiled even more.\n\nNow, seeing her so happy, he thought maybe it was because he had won both the tickets and the quiz. This must be what people meant by \"killing two birds with one stone,\" he thought, as a small smile tugged at his lips.",
        music = "60_Beaytiful_Daily"
      },
      [8] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = [[
Before the main course arrived, the waiter brought some desserts. After thinking for a moment, Victor chose a pudding. It was topped with a rich layer of chocolate sauce and whipped cream and garnished with a bright red strawberry.

He carefully wiped his fork and took a bite, but immediately put it down with a slight frown. His mother, who had been taking pictures of the concert tickets, noticed his reaction. "What's wrong?"

"I want to eat the pudding you make, Mom." The boy blurted out.]],
        music = "60_Beaytiful_Daily"
      },
      [9] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = [[
His mother paused, then burst into laughter at his little frown. His normally mature and composed face finally showed a rare hint of adorable and vivid childishness befitting his age.

"Alright, I'll make it for you."

She extended her hand, playfully poking Victor's cheek.

"Aren't you just the most adorable?"

The boy's eyes squinted from her touch, and in his slightly blurred vision, his mother's bright smile merged with the sunlight, almost like a beautiful painting.]],
        music = "60_Beaytiful_Daily"
      },
      [10] = {
        extrastory_title = "Adorable Idea",
        beijing = "Bg/3470.png",
        sentence = "For a brief moment, Victor wanted to use the secret ability he had never told anyone about—the ability to stop time. He wanted to freeze this moment, to capture his mother's smile like a perfect painting, forever bright and joyful.\n\nBut the thought quickly passed.\n\nBecause he didn't want that smile to stop. It was meant to be something alive, something that should continue to change and grow with time.\n\nHe decided that from now on, every time he saw his mother, he would bring her a beautiful bouquet, to show her that he was growing up, becoming more thoughtful and mature.\n\nThat way, he would get to see this smile more often.\n\nWith that thought, he quietly tucked this moment away in his heart.",
        music = "60_Beaytiful_Daily"
      }
    }
  },
