    [2905] = {
      [1] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/1223.png",
        sentence = [[
Boss Man didn't show up today.

Brian and DK exchanged slightly surprised looks.

"It's not like him to be late. Maybe he's sick?" "Donkey Kong" scratched his head.

"No way. Boss Man is never sick!" Brian replied. "Maybe he's just working on his homework."

"That makes sense! Hey, don't we also have homework to do? What do you say we go find him and do it together?"

"Sure!"]],
        music = "19_Daily02"
      },
      [2] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3030.png",
        sentence = [[
The two kids set off in search of their "Boss Man" while carrying their unfinished homework.

Yet, as they neared their destination, a group of unfamiliar adults barred their path.

"You can't go through here right now, kids," they said.

Dressed in military uniforms like the ones Brian and DK had only seen on television, the adults stood tall and sharp. Timidly, DK surveyed them, summoning his courage to offer the most solemn salute he'd ever performed, "We're here to find your boss... oh, I mean our boss man, sir and ma'am!"

His words drew laughter from the adults. "Oh? And who might your boss man be?"]],
        music = "19_Daily02"
      },
      [3] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3030.png",
        sentence = [[
"His name's Gavin!"

Their amusement grew. "Well, well, little Gavin is quite the figure now. He's got people calling him boss man now," they laughed warmly, and one bent down to affectionately tousle Brian and DK's hair. "Wait here for a bit, kids. Once your boss finishes his duties, maybe we can join you in your games too. What do you say?

Yet Gavin wasn't actually busy. He was merely sitting beside his mother, lost in a daydream as he watched birds flit past the window.

Initially dismissive of Brian and DK, Gavin had grown fond of their persistent company. They had insisted on treating him as their boss, and reluctantly, he had accepted, reminding him of another persistent little companion from his past.]],
        music = "19_Daily02"
      },
      [4] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3031.png",
        sentence = "Gavin wondered if Brian and DK would be upset about being stood up today. He knew he needed to apologize later. His thoughts drifted—to the airplane motor that needed a new battery, his father taking his little brother for a weeklong medical check-up without a single phone call, and a nagging fear that he might be forgotten...\n\nAmidst his reverie, the conversation between his mother and a woman in a military uniform floated to him in bits and pieces.\n\n\"I'm terribly sorry. We've been so busy recently that we've  just managed to come visit you and your mother...\"\n\n\"We've also brought some specialty medications that the hospital had just received...\"",
        music = "19_Daily02"
      },
      [5] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3031.png",
        sentence = [[
"Speaking of which, if your mother wants to give her old house a renovation, we can help get in touch with a construction crew from the city..."

His mother dismissed the offer with a wave, "No need to trouble yourselves. We're quite comfortable here. How long will you all be busy for?"

The military woman hesitated, "Uhh..."

"Don't worry about it. I know there are things you can't tell me. I get it," the boy's mother smiled. "I've grown used to it by now."

The boy never liked it when his mother smiled like that.]],
        music = "19_Daily02"
      },
      [6] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3031.png",
        sentence = [[
His mother had always been quick to smile. Meeting someone from her family, hearing a friend's joke, seeing a cute animal, or finding a beautiful flower... She would always put on the most beautiful smile.

But now, her smile was tinged with bitterness, so palpable that even the military woman averted her gaze, unable to meet her eyes, "I know he said he couldn't come, but he asked me to bring all these gifts."

She hurriedly opened a box brimming with items.

The boy's eyes lit up with delight. It was filled with things just for him: sneakers, a toy car, a swim ring, and a pair of diving goggles. "Wow! Mom, look, so many gifts!"]],
        music = "19_Daily02"
      },
      [7] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3031.png",
        sentence = [[
He thought his mother would be delighted, but her smile only deepened into something more inscrutable. Out of the blue, she asked the bearer of the gifts, "I never got your name."

"My name is Tina."

"Thank you, Tina," his mother's words were carefully measured. "And please let everyone outside the door know how much my son and I appreciate all the gifts they've prepared for us."

"No, no. This is all from Commander Albus..."

"It would be wrong for me to not thank the people who actually prepared these."]],
        music = "19_Daily02"
      },
      [8] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3031.png",
        sentence = [[
Tina's face flushed with a mix of embarrassment and sympathy. After a moment of silence, she leaned forward to hug the boy's mother and then the boy.

"Be a good boy, listen to your mother, and protect her well. Can you do that, Gavin?" Tina asked the little boy.

"Huh?" Despite feeling confused about the two adults' conversation, he could still tell both of them were sad.

He didn't want them to be unhappy, so he nodded, "I will."

A smile finally broke through her mother's expression, as beautiful as the first rays of dawn after a long, stormy night. The boy couldn't help but hug her tightly.]],
        music = "19_Daily02"
      },
      [9] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3031.png",
        sentence = [[
"I mean it," he whispered.

"I know, darling," his mother patted his head and then beckoned to Tina, "Since you've come all this way, why don't we all take a photo together? Gavin, could you fetch Grandma from Uncle Chubby's house and ask to borrow his camera?"

He nodded, sprinted to the door, then paused and pointed to the gift box in the corner, "Mom, can I go swimming in the river with my friends later?"

"The river...?" his mother hesitated.]],
        music = "19_Daily02"
      },
      [10] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3031.png",
        sentence = [[
"Don't worry, I'll go with Gavin. I'm quite the swimmer!" A cheerful voice called out as a man walked in behind Tina. Others followed him inside, Brian and DK among them, both making faces at Gavin.

An adult ruffled Gavin's hair, "Go get your grandma now, Boss Man."

"Yes Sir!" Gavin saluted like a soldier.

By the time he returned with his grandmother, everyone was positioned just right, waiting for him and his grandmother to fill the two gaps.

"Boss Man! Come over here!" Brian and DK waved.]],
        music = "19_Daily02"
      },
      [11] = {
        extrastory_title = "Visitors From Over the Mountain",
        beijing = "Bg/3031.png",
        sentence = "\"Gavin, come and stand with your mom,\" the adults smiled, pulling him into the center.\n\nGavin held his mom's hand with his left and his grandma's with his right, standing tall like the adults around him.\n\n\"Everyone smile, ready, three, two, one—say cheese!\"",
        music = "19_Daily02"
      }
    }
  },
