    [3005] = {
      [1] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = "\"Kiro, have you packed your bags?\"\n\nThe silver-haired man pressed the \"Enter\" key and turned toward the boy playing with a teddy bear in the living room. Bathed in the warm glow of the setting sun, the boy looked up and obediently nodded before rushing into his room with his teddy bear. Moments later, he reappeared, dragging a bee-shaped backpack along the floor and setting it down at the man's feet.\n\n\"...\"\n\nThe man glanced at the half-open backpack and sighed. He bent down and started taking out its contents—a Batman figurine, a globe, and a bunny doll... As he pulled out each item, his lips twitched, caught between amusement and resignation.",
        music = "303_ZQL"
      },
      [2] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = [[
Finally, he emptied the backpack and looked at the boy, who stood there, looking puzzled.

"I know I told you to pack the things most important to you. But in the rainforest, these things won't be very useful."

"Why do they become less important just because I'm going somewhere else?" the boy asked, blinking as he straightened the bunny doll on the floor.

The man typed a few keys, and a video popped up on the screen. It showed a dense rainforest, with venomous snakes slithering under the leaves and various animals watching the camera with keen eyes. The boy's eyes widened in surprise, and the man paused the video. "Remember, this summer camp is all about learning survival skills."]],
        music = "303_ZQL"
      },
      [3] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = [[
"I do remember. The teacher said we need to learn how to live on our own and not always rely on adults," the boy said as the man adjusted the boy's collar and flicked away a stray grain of rice.

"Exactly. When no adults are around, the first thing you need to do is ensure your own survival," the man said, poking the boy's belly. "You didn't pack any food. Did you ever think you might go hungry?"

"I did bring food!" the boy quickly protested. He ran back into his room and returned with a utility jacket the man had bought for the trip. The pockets were stuffed with candies and chocolates, so much so that it was close to bursting.

The man paused for a moment before nodding with a resigned smile. "Alright, you get a pass for the food test."]],
        music = "303_ZQL"
      },
      [4] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = [[
"Next, what will you do if you get bitten by mosquitoes?" the man asked, glancing at the mosquito repellent on the windowsill. He had it brought from Loveland City, but it clearly didn't make it onto the boy's item list.

The boy grinned. "Hehe... Key, don't be silly," he licked his finger and then showed it to the man, "Luby from my class said saliva keeps mosquitoes away."

"..."

Seeing the man's skeptical look, the boy eagerly offered, "You've got a bite on your hand. Let me put some on, and you'll see."]],
        music = "303_ZQL"
      },
      [5] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = [[
The man could have dodged but chose not to. Though he knew saliva wasn't exactly a potent mosquito repellent, he didn't want to dampen the boy's confidence. As with the actual repellent, he decided to sneak it into the boy's bag later, knowing the teachers would help with the rest. "Okay, you pass this test too, barely."

"Last question: I was told this summer camp would require you to work in pairs. If the teacher paired you with someone you didn't know, what would you do?"

The boy hesitated, his fingers nervously curling. "I... I don't know. What if I can't keep up? My teammate is going to hate me..."

The man smiled gently. "Why would you assume you can't keep up when you haven't even tried?"]],
        music = "303_ZQL"
      },
      [6] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = [[
"Because... I still don't know how to cook anything, and I'm the only one in my class who hasn't done a grocery run all by myself," the boy explained anxiously, his cheeks flushing with embarrassment. "That's why I want to join this summer camp. I want to learn how to take care of myself. I can't keep depending on you... If I do, I'll never grow up."

The man couldn't help but chuckle, giving the boy's head a playful rub. "Why can't you depend on me? You're only seven."

"I'm already seven years and four months old, master," the boy corrected earnestly.

"..."]],
        music = "303_ZQL"
      },
      [7] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = "\"What's so good about being an adult? You're going to regret it when you do. Besides, I also can't cook until now. Do you actually think my cooking is any good?\" The boy suddenly remembered the sweet and sour ribs his master had made recently—how something with such a tasty-sounding name could turn out so burnt and bitter was beyond him.\n\nHe quickly shook his head, but when he saw his master's expression change, he blinked his big eyes and said, \"It wasn't that bad... it was a teeny bit tasty...\"\n\n\"No need to explain. I know what you're really thinking.\"",
        music = "303_ZQL"
      },
      [8] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = "\"Now, back to the original question. Let me answer it for you.\" The man knelt down to meet the boy's gaze, pointing to the teddy bear he was clutching. \"If the teacher pairs you with another kid and you're not completely comfortable, just tell them you already have a great partner—this bear, your best friend.\"\n\n\"But...\"\n\n\"I'll say it again: You're only seven. You have all the time in the world to grow up.\"\n\n\"It's seven years and four—\"\n\nThe man gave the boy a pretended stern look, and the boy fell silent obediently.",
        music = "303_ZQL"
      },
      [9] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = "\"So just do what makes you feel comfortable and happy.\"\n\n\"Besides, this bear has always been with you. He knows you better than anyone else and understands how to help you.\"\n\n\"He's here to protect you—that's his job.\"\n\nThe boy stared at the bear for a moment, then smiled and hugged it even tighter.\n\n\"Teddy, I'm counting on you.\"\n\n\"With you here, I won't be afraid of anything.\"\n",
        music = "303_ZQL"
      },
      [10] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = [[
The man watched the boy's smiling face and couldn't help but smile himself. Then he began putting the items back into the backpack. When he picked up the globe, he hesitated for a moment before setting it on the table.

"Let's leave this one here."

"You're going to Hawaii, not on a trip around the world. What would you need this for...?"

"I'm afraid I might get lost."

"If you get lost, just call for your teacher."

"...Won't that attract wild animals? What if they eat me?"]],
        music = "303_ZQL"
      },
      [11] = {
        extrastory_title = "Summer Camp Prep",
        beijing = "Bg/2030.png",
        sentence = [[
"..."

"If there really were wild animals that could eat you, do you think I'd let you go by yourself?" "No... you're the best, master."

"..."

"Any more questions?"

"No."

"Then let's go watch some TV. You won't be able to once you leave, so make the most of it. What do you want to watch tonight?"

"Batman!"]],
        music = "303_ZQL"
