In those days, she always expressed her emotions directly. When feeling happy, she grinned and her eyes seemed to be shining; when feeling angry, she looked like a puffer fish that he couldn't help poking mischievously; when watching movies or attending charity galas, she was easy to be touched and cried sincerely, and on hearing the news of the opening of Souvenir, she jumped with great joy.]]
