    [1605] = {
      [1] = {
        extrastory_title = "Something to Protect",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
In the empty dance studio, the humidifier buzzed from time to time.

Kiro had no idea how long he had been standing there. It wasn't until his legs began to feel sore and numb that he took a step forward.

The towels and hairband hanging by the cabinet came into sight. He suddenly strode forward and threw them on the floor.

The world silently devoured his misery without showing any compassion, making his breakdown seem so trivial and quiet.]],
        music = "306_ZQL_Creation"
      },
      [2] = {
        extrastory_title = "Something to Protect",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
In the end, he dragged his numb body and walked wearily over to the towels and hairband, and slowly knelt down on the floor as if he had lost all his strength.

It was just like the day when he first picked them out.

Kiro slowly picked up the towel and hairband and carefully wrapped them in his arms. They were his only best friends by his side and the proof of his hard work. But if these proofs could be trampled on so effortlessly, then what was the point of his efforts?

After months of use, the edges of the cotton towels and hairband were slightly misshapen. He tightened his grip, recalling the many times he nearly threw them away because they were worn and old.]],
        music = "306_ZQL_Creation"
      },
      [3] = {
        extrastory_title = "Something to Protect",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = "But whenever he was about to open the trash can, the soft texture in his hand became searing hot.\n\nIt seemed to be telling him—Just wait a little longer. Hold on a little longer.\n\nIt was as if they were making their last endeavor to keep being used.\n\nHe once heard people say that life will find its way.\n\n\"Is this the way you try to find?\"\n\nHe used to stand stupidly in front of the trash can, staring at the towels and hairband in his hands and muttering to himself.\n\nThen he would stand there for a while in a daze.",
        music = "306_ZQL_Creation"
      },
      [4] = {
        extrastory_title = "Something to Protect",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
He thought of his once-depleted life which found its way in music.

It was like a light that suddenly barged into the darkness of his despair. In that world, the gold beam would always shine and light up his life.

He could see himself.

But if he couldn't preserve this purity, then could he still rely on the world that once redeemed him?

No.

Kiro lifted his head and stared at himself in the mirror.]],
        music = "306_ZQL_Creation"
      },
      [5] = {
        extrastory_title = "Something to Protect",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
That world might not be the purest, but his dream was real, and so was his passion. It was what he wanted to do as Kiro and the only way he instinctively found in his life.

He was Kiro, not 3684.

He clutched his hairband and tied it around his head again, giving himself an encouraging and reverent smile in the mirror, like he always did before the start of every practice.

"I still have two-hour dance practice to do today."

The dynamic rhythm rang out in the studio, while the sound of footsteps rose and fell. Kiro practiced hard while telling himself in his heart.]],
        music = "306_ZQL_Creation"
      },
      [6] = {
        extrastory_title = "Something to Protect",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
"It's just another ordinary day. Tomorrow will only be a better day."

Two hours later, he turned off the music, bent down, and panted heavily, but he didn't stand up immediately like he always did.

After a long while, he slowly stood up, took his violin out of the case on the floor, and sat down by the window. The soft sunlight cast on the dark brown violin. He hugged it in his arms. Or rather, he was the one being hugged.

"I will protect you."

Kiro's gaze was tender, while his voice was soft yet firm.]],
        music = "306_ZQL_Creation"
      },
      [7] = {
        extrastory_title = "Something to Protect",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
The birds outside the window chirped away as they rested on the windows.

"How nice. You guys are free."

Kiro smiled and gently reached over his fingers.

"I will be free one day."]],
        music = "306_ZQL_Creation"
      }
    },
    [1606] = {
      [1] = {
        extrastory_title = "Sail To Freedom",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
The phone ringtone broke the silence in the studio.

Kiro looked down at his phone and saw a very unfamiliar number. Perhaps it was a call from a fan, but he still picked it up.

"Hello, this is Planet Yacht Club. What can I do for you?"

Kiro was dumbfounded as the person waited patiently. After a long time, he finally realized he saw a yacht advertisement in a magazine during a shooting break a while ago, then he phoned to inquire about it out of interest.

But since he had to go to work immediately again, he told the company to contact him later.]],
        music = "308_ZQL_ViolinOnly"
      },
      [2] = {
        extrastory_title = "Sail To Freedom",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
But he didn't think... it would happen to be today.

"I have seen your advertisement and was a little interested in your... Er... yacht. How can I learn more about it?"

"In this case, you are welcome to visit our dock. What day would you like to make an appointment for?"

"Can I visit today?"

Kiro's words even surprised himself. He could feel his heart pounding but didn't know what feeling it was.

"Of course, you can. we will send you the address on the phone later. Look forward to your visit."]],
        music = "308_ZQL_ViolinOnly"
      },
      [3] = {
        extrastory_title = "Sail To Freedom",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
Kiro almost made the decision to buy the boat almost as soon as he saw it.

It sat quietly in the far corner of the dock. It was so unnoticeable, yet it caught Kiro's eye instantly in the shimmers on the waves.

Of course, when the salesman saw a young boy walking into the club, an obvious awkwardness showed on his face as he pondered how to politely ask him to leave.

"I want that boat."

Kiro didn't take his eyes off the boat and took out his bank card as the person looked at him in shock.]],
        music = "308_ZQL_ViolinOnly"
      },
      [4] = {
        extrastory_title = "Sail To Freedom",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
The boat was moored by a small harbor with a somewhat old little port. This was the place he saw on his way to the club.

He asked the people at the club to sail the boat here and told them he would ask them how to sail the yacht in a few days.

It was already dusk, with not many people around. There was only him and his boat, listening to the tide together.

The sun had half sunk below the horizon, and the sunlight was golden and distant, warmly embracing the world.

The boat had not been decorated yet. It looked slightly plain, but Kiro didn't care. He felt like he could already envision what the boat would look like.]],
        music = "308_ZQL_ViolinOnly"
      },
      [5] = {
        extrastory_title = "Sail To Freedom",
        beijing = "Activity/BirthDay/92002/img/back_21birth_thestorybg.png",
        sentence = [[
This boat was his. He told himself this in his mind over and over again. In the future, there would be someone whom he could share it with, someone most special to him.

This could be a birthday gift for myself. There might not have been a cake or a birthday song.

But this wasn't so bad.

Kiro was lying on the small deck. The sea birds were hovering in the sky divided into blue and amber. The boat was rocking with the tide. He reached out his arms like he could touch the sky.

Kiro suddenly felt like he was free to go anywhere.

Nothing can stop him.]],
        music = "308_ZQL_ViolinOnly"
      }
    }
  },
  [92003] = {
    [1701] = {
      [1] = {
        extrastory_title = "Come What May",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
This was Shaw's fifth month learning to skateboard. The other kids his age had long ago given it up, unable to endure the constant falling and the pain that came with it. In the end, it was just him still lurking around here.

The wheels glided along the ground at a regular pitch as he leaped over obstacles, made sharp turns, sped up, and did flips... the board seemed to almost flutter like a leaf under Shaw's feet as he did a joy-ride around Loveland City's largest skate park.

"Shaw! Shaw!"

Shaw grinded the skateboard to a halt and looked back.

A hefty kid with bandaids on his knees sauntered toward him. When he opened his mouth to speak, one could see a half-chipped tooth. "I finally found you."]],
        music = "10_Happy_Family"
      },
      [2] = {
        extrastory_title = "Come What May",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
Shaw let out a defiant, cold laugh. "I already beat you once, so now what do you want? To lose the other half of that tooth?"

"Why you...!" The fat kid's face went instantly red, but he jutted out his neck obstinately and pointed behind him: "It's not me. Someone else wants to challenge you!"

Shaw looked where he was pointing and saw a boy at least a whole head taller smiling at him. His foot was fidgeting a skateboard back and forth, and one look was enough to tell he was a seasoned pro.

"My buddy Joe here is on the Loveland City Youth Team," the hefty kid boasted as he folded his arms proudly across his chest, as if he himself had been on the team. "How about it? You game?"

So that's how it was. He had to go for backup.]],
        music = "10_Happy_Family"
      },
      [3] = {
        extrastory_title = "Come What May",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
With a half-frown, Shaw stepped on the end of his board, bouncing it up off the ground and catching it securely in his hand. "Of course I am. What's the challenge?"

Joe gave a shrug and said: "I don't want to give a newbie a hard time, so we'll just tic tac around obstacles. How about it?"

"Sure."]],
        music = "10_Happy_Family"
      },
      [4] = {
        extrastory_title = "Come What May",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = "*Thud—*\n\nAfter just a momentary loss of balance, Shaw fell to the ground with a heavy thud. His knees, his elbows... every jointed twinged with pain. The feeling wasn't at all pleasant, but even more grating was the sound of the fat kid's conceited laughter. It was even more irritating than the chirping of cicadas in the distance.\n\n\"Hahahaha! You lose, Shaw! Let's see you act like such a big shot now!\"\n\nThe less ability some people had, the more they ran their mouth. Shaw rolled his eyes. As he was about to wincingly pick himself up, the older boy Joe walked over and offered him a hand: \"Not bad.\"\n\n\"Thanks.\"",
        music = "10_Happy_Family"
      },
      [5] = {
        extrastory_title = "Come What May",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
The boy continued: "Although, a kid your age should get the basics down more first. You don't need to rush into trying advanced tricks like dolphin flips. You'll wipe out for sure."

Shaw's face instantly grew cold: "I don't need you to tell me what tricks I can try at what age." Without touching the outstretched hand, he got to his feet. He lifted his head and looked his opponent up and down, then asked, "Do you come here often?"

"The Youth Team practices here every day."

"Alright. Next time, I'll beat you for sure."

Shaw didn't so much as look at how Joe and the fat kid took his statement. He just brushed the dirt off his body, picked up his overturned skateboard, and walked straight out of the skate park.]],
        music = "10_Happy_Family"
      }
    },
    [1702] = {
      [1] = {
        extrastory_title = "Full Course Meal",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = "As soon as Shaw entered the antique store, the old man fired a question at him: \"And what havoc have you been wreaking today, my young apprentice?\"\n\n\"I'm hungry. What are we eating today?\" Ignoring the shopkeeper's question, Shaw put his backpack and skateboard behind the counter, then teased the dumb little parrot by the entrance—It was really dumb. After a month of teaching it, it still couldn't even say, \"Welcome\" when someone came through the door. It made Shaw wonder whether or not the old man had been conned out of money by someone again.\n\n\"All you think about is food...\" The old man put down the ancient manuscript he was looking at adjusted his reading glasses. \"Old Chan at the jewel shop next door said they made a pot of chicken soup today and want to give us some. I'll go stir fry some veggies, and you can ask if that chicken's done yet.\"\n\nShaw grunted in assent, then turned to go next door.",
        music = "19_Daily02"
      },
      [2] = {
        extrastory_title = "Full Course Meal",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
The shopkeeper got up and took a few steps toward the kitchen, then instantly turned back to the counter. He reached out and felt the rough scratch on the edge of the skateboard, unable to hold back a sigh.

The chicken soup was a bit bland, and the stir fry was a bit salty, so mixed together they were just right. Shaw held his head close to his bowl as he shoveled food in his mouth, keeping one ear focused on the news report about how Loveland City's GDP had grown by such-and-such, with the other ear listening to his teacher prattling on:

"...I'm not telling you not to have your fun. In fact, you should take some spills while you're still young and resilient, but you don't need to be reckless. This, this thing of yours..."

"Skateboard." Shaw filled in the blank for him.

]],
        music = "19_Daily02"
      },
      [3] = {
        extrastory_title = "Full Course Meal",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
"Right, skateboard. As I recall, this was purchased not one month ago, and you've already messed it up this much. You're too impulsive. You need to settle down."

What does that have to do with being impulsive? If I was really impulsive, then I'd chew through a skateboard in three days, not one month. Shaw looked at the chicken leg in his bowl as he thought this to himself.

"And another thing. Remember to check in at the shop early tomorrow. Old Chan and I are planning to go to the neighboring city and do some rummaging. You can come too and learn a thing or two." The shopkeeper tapped on the lip of his bowl with his chopsticks in a gesture to get Shaw's attention. "And tomorrow's your birthday, right? We can pick you out a gift! Ah, last time I had my eye on a snuff bottle of clear agate with animal designs on it, but then all of a sudden the guy decided not to sell..."

"I'm not going tomorrow." Shaw cut the shopkeeper off.]],
        music = "19_Daily02"
      },
      [4] = {
        extrastory_title = "Full Course Meal",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = "The shopkeeper's brow furrowed: \"What's got you in such a huff?\"\n\n\"I'm not in a huff. I have some business to take care of tomorrow. The school organized a field trip to a museum.\" Shaw looked up with a half-frown. \"The stuff I see there will be worth heaps more than those little trinkets you fiddle around with!\"\n\n\"—You little scamp!\"\n\nShaw let out a laugh, then took the chicken leg in his bowl and placed it in his teacher's: \"I'm full. I'm going to the back to do my homework Take this chicken. You need the protein more than me.\"",
        music = "19_Daily02"
      },
      [5] = {
        extrastory_title = "Full Course Meal",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
"Tsk-tsk. You say you're not feeling down, but you still won't go home?"

"I don't want to go home today. I'll go tomorrow." Shaw had gotten to the door when he suddenly thought of something and turned his head to ask, "Teacher, will you always keep this shop open?"

The question was so out-of-the-blue that the shopkeeper didn't understand. "What?"

"Nothing. I was just worried that, since you're getting so old, you'd want to give the business up some day. And then I wouldn't have anywhere to eat dinner."

The shopkeeper let out an exasperated breath and widened his eyes: "What kind of talk is that? You don't have anywhere else to get a meal? Anyway, this shop of mine will be open for another ten or twenty years. I'm still waiting on the day that you bring a nice young lady around to get my approval!"]],
        music = "19_Daily02"
      },
      [6] = {
        extrastory_title = "Full Course Meal",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
Shaw groaned and smiled: "Then you can go waiting another twenty or thirty years."

The shopkeeper's vision wasn't what it used to be, but he could clearly see that the child didn't exactly appear to be joking. After Shaw left, he suddenly thought of that horoscope he'd given to Shaw six months ago: "Ancestry is not destiny. Calms come both before and after storms..."

The boy's fate loomed over him this year. It remained to be seen how he'd tough it out. The shopkeeper shook his head and let out another sigh.]],
        music = "19_Daily02"
      }
    },
    [1703] = {
      [1] = {
        extrastory_title = "Yucky Cake",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
The next day when Shaw came, the shopkeeper had already gone off to shop for goods, leaving the shop empty save for himself.

The houses on Westmoon Street were all old, with thin walls. As he lay on the bed, Shaw could hear the chirping of birds and the voices of people outside the window. He could also hear the clamor of a traditional opera coming from the old book shop next door. "I'm like a winged dragon that can't fly, or a water dragon mired in swamp..."

Shaw rubbed his face and sat up in bed.
]],
        music = "48_Quiet_Daily"
      },
      [2] = {
        extrastory_title = "Yucky Cake",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = "The school arranged to meet up at nine o'clock so that they'd have plenty of time to set out. Shaw cursorily washed his face, then scooped up some grains from the kitchen to feed to the parrot. When he got to the counter by the front door, he suddenly realized there was something on it.\n\nWhen he walked over, Shaw discovered it was a cake box, plus a cleanly washed t-shirt.\n\nThere was also a note on the shirt written in a delicate, thin hand. He knew at a glance it was the old man's handwriting: You need to look sharp if you're going to a school function. Don't wear those same dirty clothes from yesterday. Wear this.\n\nThe clothes looked a bit familiar, probably something he'd changed out of before and forgot at the antique store. At any rate, he didn't pay it much mind, turning instead to the little cake—He knew in those ancient scrolls and paintings there were descriptions and depictions of all manner of cakes, so why did he always have to buy this same old bland type any time he bought a cake?",
        music = "48_Quiet_Daily"
      },
      [3] = {
        extrastory_title = "Yucky Cake",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
These days whenever a classmate had a birthday, they all had fancy, made-to-order cakes like red velvet or matcha Napoleon, or chocolate lava... This Westmoon Street district was probably the only place one could find this old-fashioned peach cake. The light red and green colors decorating the cake were obviously done with artificial coloring. Eating it would surely dye his tongue, and then as soon as he spoke, wouldn't his classmates have a big laugh at him?

Shaw's face was practically one big scowl, and yet the fork in his hand never stopped. The cream was made from margarine. Yuck. Inside the cake, he bit into a broken piece of egg shell. Yuck. "Happy B-Day" was spelled out using cherry jam. Super yuck...

The stupid parrot off to the side was watching with its head cocked as the boy ate bite after disdainful bite, until there was nothing left.

Shaw wiped his mouth, then swished his mouth out with the barley tea on the table before picking up the t-shirt and going back to the room to change.]],
        music = "48_Quiet_Daily"
      }
    },
