The guide looked like he had just seen his savior and pointed excitedly at him. "You there! How about you give an answer? It's okay if you're wrong. That's what I'm here for!"

"..." Shaw turned toward the guide and mumbled a few words, but his voice wasn't loud enough to be heard.

