        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
"The figures in the painting are depicted in a loose, romantic style with graceful, elegant lines. It is an especially precious treasure among silk scrolls, which is why "Picture of Learned Men" was stored in the royal collection. The only pity is that due to the taboo against leaving names of predecessors in postscripts, the only postscript to this painting that survives is an inscription by Sima Yi of the 15th century."

The youth jutted out his chin and flashed a defiant grin at the guide: "Very well, sir. You may lecture about the next item."]],
