        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
At the museum entrance, every class formed up in lines as the teachers droned on about not forgetting about homework even though it was the weekend and to remember to write a journal entry about their trip to the museum. The students all dutifully shouted out, "We will," but really their minds were already a thousand miles away, dreaming of toys and snacks.

"Shaw!" After they'd been dismissed, a classmate waved at Shaw.

Shaw walked over: "What?"

"We know you're in a bad mood because you lost to that older kid yesterday, and today's you're birthday, right? Well, Lou just happened to get the latest new video game, so let's go to his house to play." His classmate put a hand on his shoulder with a smile.]],
        music = "19_Daily02"
      },
      [2] = {
        extrastory_title = "Sink Race",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
"Who told you I lost yesterday?" Shaw asked coldly.

"Who else? That fatty. He was tickled pink yesterday," the classmate said as he patted Shaw. "But don't worry, we're all on your side. And don't let that stuff get you down. We'll have plenty of time to get revenge later..."

"If I want revenge, I won't wait until later." Shaw scowled and said, "I was going to the skate park right now. You guys coming?"]],
        music = "19_Daily02"
      },
      [3] = {
        extrastory_title = "Sink Race",
        beijing = "Activity/BirthDay/92003/img/back_21birth_thestorybg.png",
        sentence = [[
Because it was the weekend, when Shaw got to the skate park, there were already quite a few skateboarders practicing and messing around. He quickly found that guy Joe from the day before.

Shaw got right down to business: "Yesterday, you beat me. Today, I want to race you again. You game?"

Joe looked a bit surprised, as if he'd never before seen such an insistent kid before. "Look at how beat up you got yesterday. You still want to race me? Get some more practice first!"

