        sentence = "The post-it was a little crooked, so Gavin straightened it out using a fridge magnet, then went back to his own room.\n\nThe little room was filled with traces of a young boy's life. On the wall were posters of basketball stars, and the desk had a globe and some books.\n\nGavin hesitated a moment then opened his bag and took out a flier. On it were details about the model plane competition.\n\nAs he carefully read over the information, the wind blew open white curtains at the window. Yellow light outlined the straight posture of the youth and also dappled a magazine with golden light. Upon it were the faintly visible words, \"Model Plane Catalogue\".\n\nAs he was reading it, he suddenly thought of what his desk mate had said—",
