As Gavin's mom set about making a big birthday dinner for him, Gavin decided to go to the living room and fix the fan.

With the experience of making the model airplane under his belt, Gavin took a user's manual and quickly had the fan humming along again.

The fixed fan rotated leisurely back and forth, blowing out a cool breeze. As Gavin closed his eyes and felt the stream of air, his hair was blown backward, fluttering around every which way.

"It's fixed." Gavin opened his eyes, then turned his head to look at the time.

It was just past twelve. Still early.

Gavin thought for a moment, then got his model plane from his room and sat on the steps of the courtyard.]],
        music = "47_Warm_Daily"
      },
      [5] = {
        extrastory_title = "Growth Notches",
        beijing = "Activity/BirthDay/92004/img/back_21birth_thestorybg.png",
        sentence = [[
A few days ago, a piece of paint had flaked off the model plane. Gavin held a little brush and slowly gave the tail fin a new coat of paint.

The cicadas were still chirping away in the trees, and the glistening sunshine fell through the leaves, falling on Gavin's face in a mixture of shadow and light.

Gavin touched up the plane with the little brush, from time to time looking up at the gate not far away.

Today had to be the day. Even if he was late, he should come today.

Birds flew across the sky, and the sun drifted westward, until it was a semicircle being swallowed by the horizon, ushering in the evening.

Gavin sat on the steps a long time, all through the afternoon. The model plane with its graceful lines was all fixed up long ago and now sat quietly beside him.]],
        music = "47_Warm_Daily"
      },
      [6] = {
        extrastory_title = "Growth Notches",
        beijing = "Activity/BirthDay/92004/img/back_21birth_thestorybg.png",
        sentence = [[
But no one ever came through that gate.

A few leaves were blown by the wind onto the wings of the model plane. Gavin reached out and picked them up.

He held the leaves in his palm, looking on them with downcast eyes and thinking about something.

With a sudden creak, Gavin heard the sound of a gate opening in the distance, followed by the sound of footsteps.

Gavin instantly sat up straight, but also quickly turned his head.

The gentle dusk light enveloped him, lighting up his up-turned lips.]],
        music = "47_Warm_Daily"
      }
    },
    [1806] = {
      [1] = {
        extrastory_title = "Blessed Heart",
        beijing = "Activity/BirthDay/92004/img/back_21birth_thestorybg.png",
        sentence = [[
The people coming in through the gate were his maternal grandfather and grandmother.

They were carrying a birthday cake, all smiles as they walked toward Gavin.

The grandfather threw his arms around Gavin.

"Happy birthday, Gav!"

Gavin's grandmother jiggled the cake back and forth with a wide grin.

"Grandma brought you your favorite cake for your birthday, Gav!"

"Thanks, Grandma and Grandpa."]],
        music = "404_Hazy_Starry_Night"
      },
      [2] = {
        extrastory_title = "Blessed Heart",
        beijing = "Activity/BirthDay/92004/img/back_21birth_thestorybg.png",
        sentence = [[
Gavin took the cake off his grandmother's hands, then went with them into the living room. Before walking up the stairs, Gavin took one more look at the gate.

The gate was still placidly shrouded in the dusk glow, waiting together with Gavin.

But even late into the night, it hadn't been pushed open again.

Noticing Gavin's uncharacteristic silence, Wardia followed his gaze toward the gate outside and realized something.

But Wardia didn't say a thing. She just gave a pause, then put on a big smile and opened up the cake box.

"Happy fourteenth birthday to our little birthday boy!" His grandfather and grandmother grinned and sang happy birthday.]],
        music = "404_Hazy_Starry_Night"
      },
      [3] = {
        extrastory_title = "Blessed Heart",
        beijing = "Activity/BirthDay/92004/img/back_21birth_thestorybg.png",
        sentence = [[
"Happy birthday to you, happy birthday to you. Happy birthday to you, happy birthday to you..."

After singing the song, Gavin's mother looked toward him and said gently:

"Make a wish, Gav."

As he looked at the cake, Gavin fell silent for a moment. Then, he silently said to himself:

It didn't matter that he didn't come back. It didn't matter if Gavin didn't have his approval. It was his birthday today all the same, and he was another year older.

He could help his mom fix the fan and look after this house with his own power.]],
        music = "404_Hazy_Starry_Night"
      },
      [4] = {
        extrastory_title = "Blessed Heart",
        beijing = "Activity/BirthDay/92004/img/back_21birth_thestorybg.png",
        sentence = "So—\n\nIt didn't matter.",
        music = "404_Hazy_Starry_Night"
      },
      [5] = {
        extrastory_title = "Blessed Heart",
        beijing = "Activity/BirthDay/92004/img/back_21birth_thestorybg.png",
        sentence = [[
After finishing dinner, the whole family sat in the courtyard enjoying the cool evening air.

Gavin's grandfather and grandmother were pleasantly surprised when his mother told them Gavin had won first place in the model plane competition.

"Really, Gav? That's incredible. Isn't it hard to make a model plane? What kind of reward do you want? We'd be happy to give it to you."

"I don't want any kind of reward."

His grandfather insisted.

"What? You're too old now for a little reward? Tell us. Think of it as a gift from your grandma and grandpa."

Wardia slipped in a few words. "Your grandparents are trying to make a nice gesture. Just accept."
]],
        music = "404_Hazy_Starry_Night"
      },
      [6] = {
        extrastory_title = "Blessed Heart",
        beijing = "Activity/BirthDay/92004/img/back_21birth_thestorybg.png",
        sentence = [[
Gavin lowered his eyes and thought for a moment, then looked up and spoke in a low voice:

"Alright then. Every year from now on, I want us to all spend this day together like this."

He paused. In his eyes, there was a hint of a smile, warm and serene.

"Eating cake. Chatting. And singing happy birthday."

"That's easy, isn't it? Every year from now on, Grandma and Grandpa will be sure to come and celebrate your birthday with you and your mom, Gav."

"Then it's settled."]],
        music = "404_Hazy_Starry_Night"
      },
      [7] = {
        extrastory_title = "Blessed Heart",
        beijing = "Activity/BirthDay/92004/img/back_21birth_thestorybg.png",
        sentence = [[
The night breeze blew, tousling the bangs on Gavin's forehead and revealing his pair of clear, amber irises. He looked back into the courtyard and say his grandparents and his mom chatting about this and that, everyone smiling and laughing.

It was a house that had been mended by love, with lots of warmth and lots of hope for the future.

The young man's heart was enveloped by this warmth and hope, making him feel like he wasn't alone in this moment.

The Milky Way still shone brightly, and under the star-filled sky, the tree that had grown for so many years in the courtyard stood silently, as if it would for years and years to come.]],
        music = "404_Hazy_Starry_Night"
      }
    }
