  [92005] = {
    [1901] = {
      [1] = {
        extrastory_title = "Boy Genius",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
There weren't many flights coming and going in the early morning at Heathrow. Fighting off the urge to sleep, Lucien pulled his luggage along the desolate corridor. It was a bumpy flight from start to finish, so he almost hadn't slept at all. Now, all he wanted to do was to find the person sent to pick him up as quickly as possible. Perhaps he could still get a little sleep on the way to the award ceremony venue.

The meet-up went smoothly. Lucien slumped back in the back seat of the limousine and breathed a sigh of relief.

"Have some breakfast, Mr. Lucien." The person in the front passenger's seat handed him a brown paper sack, and a familiar smell hit his nose, awakening distant memories.

"It's pancake. The sponsors know that you're often too busy to have breakfast, so they bought this for you early morning."]],
        music = "30_WarmSnow"
      },
      [2] = {
        extrastory_title = "Boy Genius",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = "Lucien was taken aback for a moment, then took the paper sack. Its warmth radiated into his palms.\n\n\"Thank you.\"\n\n\"And have this too. A souvenir gift that the committee specially prepared for each participant.\" Lucien took the ornate box the man handed to him. The cover was embossed with gold letters — FEATHER QUILL PEN SET.\n\n\"I picked out the most unique one just for you. I'm sure a boy of your age will like it.\" As he spoke, the man gave Lucien a wink.\n\nLucien nodded politely without saying anything. Lucien's somewhat aloof demeanor didn't put a damper on the man's enthusiasm. He continued about his work as Lucien's 'welcome wagon', chattering non-stop about the award ceremony.",
        music = "30_WarmSnow"
      },
      [3] = {
        extrastory_title = "Boy Genius",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
"When we learned that one of the award winners was only fourteen years old, the sponsors and the media got quite excited."

"I believe there's a saying that true heroes always start young. But you should know that this international award has a hundred-year history in the scientific community, and to date you are the youngest recipient yet."

"Not to mention how complicated the field that you did your research in is. Exceedingly few people would ever take on this topic."

Lucien turned his gaze away from looking out the window and blinked his exhausted eyes. "Thank you. You flatter me. I was just doing my best to complete a homework assignment. All it took was a good bit of time and focus, that's all. It's not as amazing as all that."]],
        music = "30_WarmSnow"
      },
      [4] = {
        extrastory_title = "Boy Genius",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
Lucien's voice sounded a bit hoarse, probably because he was at the stage of voice change. There was also an almost imperceptible exhaustion in his voice. Waves of drowsiness buffeted his brain, and he struggled mightily to stay awake. After mulling over his words, he said in a tactful tone:

"Before we set out, you mentioned that it would take over an hour to get to the award ceremony venue, yes?"

The cheery male voice perked up again from the front passenger seat. This time he turned right around to face Lucien, going on at length about the various city landmarks they would pass along the way, clearly not understanding what Lucien had been trying to imply.

Lucien was getting a little impatient. Perhaps he would have to use the most direct of methods to communicate more clearly. And so, covering his mouth, he quite pointedly let out a huge yawn and then made an apologetic smile.]],
        music = "30_WarmSnow"
      },
      [5] = {
        extrastory_title = "Boy Genius",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
"I am truly sorry. I'm a bit sleepy. Might I sleep a bit?"

The car interior finally fell silent. Lucien closed his eyes and got a brief respite.]],
        music = "30_WarmSnow"
      }
    },
    [1902] = {
      [1] = {
        extrastory_title = "Award-winning Journey",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
"Hello, everyone. I'm Lucien. It's an honor to receive this award..."

Lucien had memorized his acceptance speech until he knew it backwards and forwards, so he delivered it with ease and confidence, and even with a poise and maturity that belied his age.

Since he was little, Lucien had been to no small number of award ceremonies, so this was not at all unfamiliar territory to him. But unlike those other awards for young science prodigies he'd gotten before, this time he had been selected for a proper international science award, without restriction for age or nationality. Transcending the constraints of qualifications and seniority, he stood there among all the adults also winning awards, receiving this worldwide accolade as an equal.

For him this was indeed a day of extraordinary significance. Not only because of the value of the award itself, but for other reasons as well.]],
        music = "30_WarmSnow"
      },
      [2] = {
        extrastory_title = "Award-winning Journey",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
"Science is egalitarian. It surveys impartially and calmly, accepting every challenging inquiry and opening up a path for exploring the world's mysteries, for seeking truth, and for finding answers to everyone. It is its most alluring aspect, and also the reason why I shall never halt my steps."

"...and now, I extend my gratitude to all of my predecessors who devoted themselves to the work of science."

Lucien made a small bow to a wave of applause from the crowd.

The bright spotlight was a bit too dazzling as he stood alone on the spacious stage, unable to see the audience in the darkness. But for some reason, suddenly before his eyes appeared two distinct, yet blurry figures. They stood in the very back of the crowd and appeared to have their eyes locked on him up on the stage, clapping and smiling.]],
        music = "30_WarmSnow"
      },
      [3] = {
        extrastory_title = "Award-winning Journey",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
Lucien's fingers curled up as if on their own, and his wide eyes began to sting a little.

When he got back to his hotel room, it was already night.

In actuality, the award ceremony was already over at noon, but all of the various media interviews afterward had taken up so much time. Lucien had wanted to turn down these formalities, thinking that after a brief rest at the hotel he could have a look around this unfamiliar city. However, the generous hospitality of the media and the sponsors left him with no choice but to take the interviews along with the other participants.]],
        music = "30_WarmSnow"
      },
      [4] = {
        extrastory_title = "Award-winning Journey",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
Words like "genius" and "youngest award recipient" were bandied about repeatedly on the lips of the reporters. The constant camera flashes made even Lucien a bit overwhelmed, poised though he was for his age. He even began to lose track of the questions the reporters were vying to ask him. All he could do was remind himself to keep his composure as he did his best to gracefully answer every question. If he had to choose one thing from the day that he could've done better, it would probably be when he froze up answering one particular question.

"Where does your interest in science come from? Was there some moment that got you into science research?"

He poured himself some water, putting aside these jumbled thoughts as he did some basic washing up before bed. Then he took out a camera from his backpack, placing the used up roll of film carefully into its protective container to be developed later. Then he put in a fresh roll of film in preparation for tomorrow.]],
        music = "30_WarmSnow"
      },
      [5] = {
        extrastory_title = "Award-winning Journey",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
According to one of the event staff today, tomorrow morning the sponsors had plans to take him and the other award recipients on a short trip to Venice. It was said to be a floating city built upon the water, sinking lower every year.

Lucien put his ID and train ticket in his wallet, then took out a novel he'd been reading lately and lay down on bed.


He looked at his watch, set an alarm, and told himself:
Tomorrow, you've got to get up early, so just finish this chapter then get to sleep.
]],
        music = "30_WarmSnow"
      }
    },
    [1903] = {
      [1] = {
        extrastory_title = "Existence & Imprints",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = "*Cli-ick*.\n\nA flashbulb popped off, capturing a group photo in front of the Venice train station.\n\nLucien pursed his lips together and straightened up his posture, but there was a faint sense of urgency in his eyes. It's not that he had an aversion to these sorts of formalities, but right now he had more pressing business to attend to — getting acquainted with and exploring this unfamiliar city.\n\nWhen he was finally seated on a gondola, he felt a small pang of shock. Seeing this water-dependent city with his own eyes was an experience he'd never had before. It was an indescribable feeling that seemed to well up from inside him. Cloudy though the weather was, he was full of excitement on the inside. It was the exact same feeling he got every time he went in search of some answer.",
        music = "30_WarmSnow"
      },
      [2] = {
        extrastory_title = "Existence & Imprints",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
The gondola pulled up before a plaza. Lucien got out his camera and aimed it with relish in all directions.

"You really like taking photos, don't you?" An older gentleman who had been especially attentive to Lucien leaned in close to his lens. "Your camera is quite nice too." As he said that, he gave an approving thumbs up.

Lucien nodded with a sincere smile and said, "Thanks. My father gave this to me."

A loud call from the tour leader cut off their conversation.

"We have now arrived at Venice's famous Biblioteca Marciana. You have two hours to look around, immediately after which we will board a ferry to take in the sights at two neighboring islands." Lucien's brow furrowed as he took a look at the guidebook in his hands. After a moment's consideration, he approached the tour guide.]],
        music = "30_WarmSnow"
      },
      [3] = {
        extrastory_title = "Existence & Imprints",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
"Might it be possible to make some changes to my own itinerary? I'd like to stay at the library until everyone returns from the islands."

The tour guide patted Lucien on the shoulder, then stretched out a finger and wagged it mysteriously. "Those two islands are quite interesting. One is Murano Island with its world-famous glass artisans, and the other is Burano, known for its lively painted houses. I'm sure you would love it, young man."

Lucien pursed his lips and tried again to persuade this adult before him. "But I'd still rather stay at the library. Please rest assured, I won't go wandering off."

Faced with the determined gaze of this young prodigy, the tour guide shrugged his shoulders in resignation and cautioned him to look out for his safety.]],
        music = "30_WarmSnow"
      },
      [4] = {
        extrastory_title = "Existence & Imprints",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = "As he walked up and down the library taking in the rich scent of the books, Lucien congratulated himself on his decision — there were many ways to learn about the things that interested him here. Anything he wanted to know about this city, and this world, was at his fingertips.\n\nThis fresh yet familiar feeling made him feel incomparably relaxed at the moment.\n\nHe sat at a table in the reading area and flipped through a book with gusto when suddenly his hand halted mid-turn.\n\nOn the library lending card on the inside cover of the book, a familiar name jumped out at him.\n\nLucien suddenly had a fleeting hallucination. He seemed to see that figure in a white lab coat that would occasionally appear in his dreams. It was at some point in the past that that figure had sat right where he was sitting now, diligently reading the very book he had in front of him.\n",
        music = "30_WarmSnow"
      },
      [5] = {
        extrastory_title = "Existence & Imprints",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
A strange feeling and warmth flowed from the pages of the book, through Lucien's fingertips and spread through his entire body. He stared in a daze at that name, running his fingertip over the letters without realizing it. He did it with great caution and tender care, as if the slightest bit of pressure would erase the name from the book.

All outside noise seemed to fade away, and the counters of his surroundings blurred away until all that was left was this name and Lucien himself.

After a long while, an almost imperceptible smile rose on his lips.

"So you came here before too."

"Is this an imprint that you left behind in this world?"]],
        music = "30_WarmSnow"
      },
      [6] = {
        extrastory_title = "Existence & Imprints",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
Lucien blinked his eyes and sat like that for a long time, then put the book back on the shelf exactly where it was before, like it was untouched. Glancing at the time, he quickened his pace out of the library and found the group in the middle of boarding the ferry.

"Sorry, I've changed my mind."

The group took him in gladly, and he set out together with everyone to the neighboring islands. Lucien looked off at the little island in the distance, his scarf fluttering in the wind.

Perhaps you'd left something behind there too before?]],
        music = "30_WarmSnow"
      }
