    [1904] = {
      [1] = {
        extrastory_title = "Record the World",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
Unfortunately, Lucien didn't make any new discoveries.

Not that he had any great hopes that he would, but when the feeling of emptiness really hit, he couldn't help but feel a bit down.

Those buildings touted for their bright colors weren't anything special to him. All he noticed was a cute doll someone had left out on one of the balconies, looking as if it was waiting to be warmed up by the sun before going in to soothe the crying infant. Or the withered potted plants that filled the balcony next door, and their owner seemed to have forgotten about the little patches of life waiting just on the other side of the curtain.

These were things discrepancies that Lucien could perceive, it's just that they had nothing to do with him.]],
        music = "61_Feeling_Blue"
      },
      [2] = {
        extrastory_title = "Record the World",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = "Lucien let his gaze fall down, where he noticed that he had been playing with a pebble with his foot. Almost at the same time, the tiny little pebble was wetted by a drop of rain, staining it like spilled ink.\n\n\"It's raining.\"\n\nLucien spoke softly, as if talking to himself.\n\nThere was a slight chill to the rain water, so Lucien pulled his scarf tighter around his neck as he looked out from the Bridge of Sighs —\n\nPedestrians passed in an unending stream. Some were getting into gondolas and taking keepsake photographs while others were recording the singing gondoliers.\n\nThe fine drizzle vanished into the canal water. All one could see were the waves of water lapping against the stone walls of the canal as the gondolas glided by, constantly changing the hue of the rocks from light to dark, and from dark back to light.",
        music = "61_Feeling_Blue"
      },
      [3] = {
        extrastory_title = "Record the World",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
Lucien couldn't help but think about the story of this floating city and the inexorable fact of its sinking year by year. But all of these changes also lent a significance of impermanence to this place.

Suddenly, the sound of a camera shutter came from nearby. Lucien tilted his head and watched as a blonde-haired man took a photo of his children. He was constantly adjusting his shooting angle, with a happy smile plastered to his face.

"Gosh, kids, you're already so much taller than last time. I don't even need to squat down to get the shot~"

Lucien froze up for a moment, then looked down at the camera in his hand.

Even in a place and a culture on the opposite side of the world, the way love expresses itself is always so similar.]],
        music = "61_Feeling_Blue"
      },
      [4] = {
        extrastory_title = "Record the World",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
After a long while, he lifted his camera and snapped a photo of the Bridge of Sighs.

Maybe I have to choose to record the world precisely because everything fades and passes. I am recording the world as I see it. At the very least, the Bridge of Sighs in this moment, from this angle, belongs to me.

With that thought in mind, a hint of a smile formed on Lucien's lips.

Some birds flapped across the surface of the water with an urgency like they were searching for the way home, unexpectedly intruding into the frame of Lucien's shot. As he watched their flight path, he panned his camera and recorded this sight.

"Run along home."]],
        music = "61_Feeling_Blue"
      },
      [5] = {
        extrastory_title = "Record the World",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = "Lucien chuckled lightly and was about to turn and go to the next stop in the tour when —\n\nHis shoulder was jostled by a passerby, and the camera in his hand went crashing down onto the cobblestones below.\n",
        music = "61_Feeling_Blue"
      }
