    [1905] = {
      [1] = {
        extrastory_title = "Missing & Pursuing",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
Lucien sat quietly on a chair by the door in a shop. The wooden sign overhead was carved with the word "Commuovere".

An hour prior, he politely expressed his apologies to the tour leader.

Because he'd accidentally dropped his camera and had to go find a repair shop, he might be unable to go along with the group to the next activity. The tour leader was understanding and was about to get someone to go along and help him, but Lucien turned down the offer.

Luckily, Lucien found this shop tucked away in a little alley. The sounds of gears and clock hands reverberating through the shop put him at ease. The only thing was that the repair was taking longer than he thought it would, and the rays of the setting sun through the window mercilessly stretched the repairman's shadow longer and longer.]],
        music = "204_Affectionate_Scene"
      },
      [2] = {
        extrastory_title = "Missing & Pursuing",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
What if the camera couldn't be fixed?

When this supposition arose in his mind, an ineffable feeling came over Lucien, not quite like the dull process of exploring the mysteries of the world, nor like the feeling of running into a snag in the search for answers.

It was more like... a worry and fear at the severing of some important connection.

Lucien took a deep breath, trying to allay that emotion welling up in his chest. This was a thing that he was not too good at, and his weak spot.

All these years, Lucien had always remembered the answer of the question he was pursuing. Or one could say, he was carrying out that one little wish on his own.]],
        music = "204_Affectionate_Scene"
      },
      [3] = {
        extrastory_title = "Missing & Pursuing",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = "Even though now he could easily arrive at the answer to similar questions, and even though every step he took now was a stride in the direction of finding that answer, he still wanted to be a bit faster.\n\nIt would be fixed.\n\nEven though he had no evidence, he still answered that question with a quiet whisper. Lucien told himself that perhaps one didn't need to rely on reason at a time like this.\n\nThe sky eventually grew dark. Lucien happened to look up and saw a burning candle placed on a window sill overhead, wavering with a fiery glow behind the protection of a simple piece of glass. As he regarded that little bead of light, he was dimly reminded of something —",
        music = "204_Affectionate_Scene"
      },
      [4] = {
        extrastory_title = "Missing & Pursuing",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
When a person disappears from this world, many of their imprints fade along with them, as if they never existed in the first place.

Just like that candle. Protected though it was behind the glass, its flame would come to an end too.

Just like the name left on that library card, perhaps one day it would be quietly replaced by a brand new card, and it would be like the name never existed.

Many things in the unfolding of people's lives or stories turn into words like "many years from now" and hedging words like "seemingly", "probably", and "possibly".

But even so, Lucien felt a twinge of rejoice.]],
        music = "204_Affectionate_Scene"
      },
      [5] = {
        extrastory_title = "Missing & Pursuing",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = "Rejoice that his memory was so good, keeping even distant memories vivid, fresh, and ever-present.\n\nPerhaps he should start a new competition of pursuit —\n\nThis time, he would race with time itself and never let oblivion catch up to him.\n\nThe gears in the air turned at their same leisurely, steady pace while Lucien looked on serenely at that candle for quite some time.",
        music = "204_Affectionate_Scene"
      }
    },
    [1906] = {
      [1] = {
        extrastory_title = "Time's Gift",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
When Lucien got back the camera, the canals were shrouded under the cover of the night.

He walked more briskly than before, and his fingers clutched at the camera more tightly, seemingly worried that this afternoon's incident would repeat itself.

Up ahead, there was a little bookshop.

The rich smell of books seemed to be calling him more strongly today than usual. After a moment's thought, Lucien pushed open the door and entered. Surveying his surroundings, he realized this bookshop wasn't organized by genre. The books were all piled up in random stacks, yet they were well taken care of. It was like a bibliophile's private library.

"Hurry up, over here."]],
        music = "204_Affectionate_Scene"
      },
      [2] = {
        extrastory_title = "Time's Gift",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
An urgent-sounding voice wafted over from the end of the bookshelves. Through the cracks, Lucien could see two blonde-haired, blue-eyed men struggling to move a wooden crate filled with books up onto the top of a shelf. There was a huge wet spot on the bottom of the crate. In light of the distinctive nature of this city, Lucien looked up at the clock on the wall and came to a rough hypothesis. Mid-November was the high-water period here, so he figured they were trying to save some books from being flooded.

Lucien thought about whether he should go help them. After all, books getting soaked was a distressing affair. But from what he could make out, the pair seemed to be discussing how to mitigate the flooding. After giving it a thought, Lucien decided not to disturb them and continued perusing the shelves. Amidst the sounds of frantic footsteps and hurried yet measured discussion, Lucien diligently selected a few books that he could curl up in bed with.]],
        music = "204_Affectionate_Scene"
      },
      [3] = {
        extrastory_title = "Time's Gift",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
When he got to the register, the shopkeeper also happened to be close enough to hop over and attend to him. While the books were being bagged up, Lucien's gaze came to rest on a metal wrack stocked with postcards.

"We've just started offering a postcard mailing service. Lots of tourists send them home to family and friends. Would you like to write one?" The shopkeeper seemed to notice what Lucien had been eyeing and raised his straw-colored eyebrows invitingly.

Lucien said nothing, seemingly mulling something over.

A long time passed before he finally picked out a postcard with a scene of the Bridge of Sighs on it. Then he took a pen from the shopkeeper and leaned over a desk. He hesitated a moment at the address line, then wrote down an address in Loveland City.]],
        music = "204_Affectionate_Scene"
      },
      [4] = {
        extrastory_title = "Time's Gift",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
Actually, he hadn't been back in a long time, and didn't even know when he would go back. Yet still, he wrote with great care and attention to detail, even more diligent and careful than when doing calculations or carrying out experiments.

There was a lingering dampness to the air after the rain, and a chill breeze swept through the cramped space. He clenched the pen between his fingers, and he could even feel a slight perspiration around his eyes. But there was too much he wanted to say, to them and to his future self.

When he wrote down the final word, Lucien let out a long sigh of relief.

He carefully placed the thin postcard gently into the mailbox.]],
        music = "204_Affectionate_Scene"
      },
      [5] = {
        extrastory_title = "Time's Gift",
        beijing = "Activity/BirthDay/92005/img/back_21birth_thestorybg.png",
        sentence = [[
In a flash, he seemed to see a little house with white brick and red tile under the setting sun. In the courtyard, the man in the white lab coat walked past a telescope to the mailbox and took out this postcard that had crossed the ocean in a spirit of yearning. His brow perked up in satisfaction, and he turned to say something to someone inside the house. A woman dressed in loungewear opened the door at the sound of his voice and smiled, then chided him gently to get inside and help her prepare dinner.

The clarion sound of a trumpet and the sight of a swaying osmanthus receded upon the breeze, gradually blurring into a haze.

The canal-side clock tolled, reverberating through the night air.

This day was over.]],
        music = "204_Affectionate_Scene"
      }
    }
  },
  [92006] = {
    [2001] = {
      [1] = {
        extrastory_title = "Greetings From Afar",
        beijing = "Bg/1421.png",
        sentence = "After several days of rain, the weather finally cleared up. The warm sunlight poured in from the French windows, luring the green plants in the corners to stretch themselves and climb up the window edges. Victor stood in front of the window with a cup of coffee, overlooking the endless stream of people weaving between the buildings. The lingering, bitter aroma mixed with the mellow incense of the room, and whirled between breaths. At this moment—the phone on the desk vibrated.\n\nVictor sipped the coffee before turning to pick up the phone. A smile flashed at the corners of his lips.\n\nHe sat down in his chair, took off his glasses, and answered the call.\n\n\"Aunt Grace.\"",
        music = "04_Normal"
      },
      [2] = {
        extrastory_title = "Greetings From Afar",
        beijing = "Bg/1421.png",
        sentence = "The video call came from the distant Atlantic coast—a relative was getting married in Spain and sent their invitation. Despite the long distance, Victor's father felt obligated to attend, so he went over with Aunt Grace. Today was the second day of their arrival. Victor planned to let them rest before contacting them.\n\n\"Victor, your father and I just got up. We're just calling to let you know we've arrived safely.\"\n\nOn the screen, Aunt Grace waved at him, then pointed the camera at his father, who was eating breakfast and greeted him by raising his coffee mug. Victor raised his own coffee cup in reply.",
        music = "04_Normal"
      },
      [3] = {
        extrastory_title = "Greetings From Afar",
        beijing = "Bg/1421.png",
        sentence = [[
"So, Aunt, how was the journey? Are you tired?"

"No, not at all! You have no idea how soothing the sunshine and breeze are over here! Your father and I are staying at a suburban estate, and we can see the sea the moment we open our eyes. Oh, and I heard some of your uncles said on the way that the wedding will be on a cruise ship. Had I known it was a cruise wedding, I would've brought a couple of scarves with lovely colors. It'll get so windy at sea. I bet it's gonna be freezing."

Victor chuckled and replied, "The weather's nice today. You can walk around town if you have the time. You may even be able to find some nice scarves."]],
        music = "04_Normal"
      },
      [4] = {
        extrastory_title = "Greetings From Afar",
        beijing = "Bg/1421.png",
        sentence = [[
This seemed to be what Aunt Grace had planned to do. She seconded the moment Victor raised the suggestion and dragged her brother to plan the trip together. As Victor watched his father's helpless frown, he couldn't help teasing, "Dad, you haven't travel around for a long time. It'll be good to walk around with Aunt Grace."

"You know what your father is like. He shuts himself inside all the time. He would only go for a walk when your mother was still around." Despite complaining, the smile remained bright on Aunt Grace's face. She showed Victor the scenery of the manor on the phone, "Victor, the owner of this manor is also in the wine business and he has a collection of fine wines. We ordered two boxes from his wine cellar when we had dinner with him last night. We'll send them to you today."]],
        music = "04_Normal"
      },
      [5] = {
        extrastory_title = "Greetings From Afar",
        beijing = "Bg/1421.png",
        sentence = [[
"Your birthday is in two days. They are your birthday present. I can't make you longevity noodles this year, so remember to make some for yourself."

Aunt Grace put the phone in front of her, talking while having her breakfast, "Your father said you're an adult now and more than capable of taking care of yourself. So I'm not gonna nag. We're fine here, so don't worry about us. I'll get your father to give you a ring again after the wedding."

Victor nodded, "Okay. Let me know after you confirm when you're coming back. I'll book the tickets for you."]],
        music = "04_Normal"
      },
      [6] = {
        extrastory_title = "Greetings From Afar",
        beijing = "Bg/1421.png",
        sentence = [[
Aunt Grace waved, "Okay. I'll let you get to work. Happy birthday, Vic! Don't forget the longevity noodles."

Victor smiled and waved as he hung up. Silence returned to the room in an instant.

At the same time, someone knocked on the door, "Excuse me, Mr. Victor. The representative of YH Securities is here."

Victor stood up and buttoned up his suit, "I'll be right there."]],
        music = "04_Normal"
      }
    },
    [2002] = {
      [1] = {
        extrastory_title = "Employee Perks",
        beijing = "Bg/1441.png",
        sentence = [[
"What exactly is this meeting about? Why does it need two more days? The CEO has another meeting scheduled on the morning of the 14th, so the 12th and 13th are the best choices if we need to adjust schedule. Goldman, can you ask Mr. Victor if he has other plans for these two days? If not, I'll go book the flights and hotel."

In the break room, the administrative staff member was checking Victor's schedule. She took over the coffee while chatting with Goldman sitting at the bar table with his takeaway.

Goldman held the spoon in his mouth as he checked his phone.]],
        music = "52_Daily03"
      },
      [2] = {
        extrastory_title = "Employee Perks",
        beijing = "Bg/1441.png",
        sentence = [[
"If we put them on the 12th and 13th... the schedule is much more packed indeed. And we come back on Friday, which can save us working overtime for one less day." He went through the itinerary in his head, figuring out whether there was a better option. "But the 13th is Mr. Victor's birthday. I don't know if he has other non-work related plans..."

"Just ask him. I doubt that he will. I can't imagine a busy man like him doing anything other than working on his birthday..."

The admin staff member added half a packet of sugar to the coffee and stirred it clockwise twice, "Unless he has a girlfriend, then maybe his girlfriend will celebrate it with him."]],
        music = "52_Daily03"
      },
      [3] = {
        extrastory_title = "Employee Perks",
        beijing = "Bg/1441.png",
        sentence = [[
"Don't be ridiculous. I practically spend all twenty-four hours with him. The only thing he does apart from work is more work. He simply doesn't have a minute to date anyone. I don't think he'll have a girlfriend to celebrate birthdays with him in the next ten years, unless he could somehow magically add twenty-four more hours to a day." Goldman inhaled the meat in the bowl and saw Victor walking towards them the moment he looked up.

"M-Mr. Victor..." He hurriedly closed the lunch box and wiped away the oil stains on the table with paper towels.

Victor shot him a glance, "I'm just walking past. I heard nothing."]],
        music = "52_Daily03"
      },
      [4] = {
        extrastory_title = "Employee Perks",
        beijing = "Bg/1441.png",
        sentence = "The admin staff member interrupted at the perfect time. \"Mr. Victor, we were just talking about the meeting schedule. I need to book the flights and the hotel soon. The 12th and 13th seem to be the best days, but since your birthday is on the 13th, we want to know if you have plans for your birthday.\"\n\nVictor nodded, \"No. Let's schedule it for the 12th and 13th. Thank you.\"\n\n\"By the way, Mr. Victor—\" The admin staff member seemed to remember something and ran back to her table to take a small gift bag from a drawer.",
        music = "52_Daily03"
