    [2003] = {
      [1] = {
        extrastory_title = "A Friend's Gift",
        beijing = "Bg/1152.png",
        sentence = [[
Another red light.

The phone rang the second the car stopped. Victor answered the call on Bluetooth, then Ronan's "loud" greeting voice rang out. Victor turned down the volume as he smiled and sighed.

"What's causing you to postpone your trip to Loveland this time?"

Ronan chuckled, "I called to send my sincere apologies. But you make it sound like I stand you up all the time."]],
        music = "60_Beaytiful_Daily"
      },
      [2] = {
        extrastory_title = "A Friend's Gift",
        beijing = "Bg/1152.png",
        sentence = "Victor stared at the red light, \"Haven't you?\"\n\n\"Anyway, I do have some urgent matters to tend to this time. I met a prestigious local professor here in India, and he promised to help me sort out the details of the documentary, but he's only got twenty days off, so I need to fight against time. But, I won't forget about your birthday of course—I just so happen to have got my hands on an antique painting here. I'll give it to you when we meet. I'm sure you'll like it.\"\n\nVictor couldn't help teasing, \"How innovative. As always.\"",
        music = "60_Beaytiful_Daily"
      },
      [3] = {
        extrastory_title = "A Friend's Gift",
        beijing = "Bg/1152.png",
        sentence = [[
"You're the one to talk! When was the last time you did something that wasn't work? Who's the innovative one here?" As Ronan spoke, Victor could hear people laughing and joking around from the other side of the phone, to which he laughed, "Sounds like you've gained a lot on this India trip."

"Let's go for a drink after I go back to Loveland City. I'll tell you about it in detail. We said we were gonna go for a drink for my birthday last time, but we still haven't managed to." Ronan paused a little before he suddenly exclaimed, "...Now that I think about it, it's been over six months since we last met. Gee, where has the time gone?"]],
        music = "60_Beaytiful_Daily"
      },
      [4] = {
        extrastory_title = "A Friend's Gift",
        beijing = "Bg/1152.png",
        sentence = [[
"How come we didn't celebrate your birthday together?" Victor recalled, "If I remember it correctly, you had to help a friend. Has it been sorted now?"

"Of course. It wasn't a big favor." Ronan said and sighed, which he didn't do so often, "Are birthdays just not as important anymore when you're adults? Work, friends, or anything else has suddenly become more important than celebrating your own birthday."

The red light counted down to sixty seconds. Victor glanced at the messages constantly popping up on his phone, then calmly swept his gaze across the crowd walking across the crosswalk, "That's probably because growing up means stop putting yourself first."]],
        music = "60_Beaytiful_Daily"
      },
      [5] = {
        extrastory_title = "A Friend's Gift",
        beijing = "Bg/1152.png",
        sentence = [[
"...True." Ronan paused, "But shouldn't we be doing the opposite?"

"Indeed." Victor scanned his calendar, "Are you still flying to Europe next month after India? I will be in France for three weeks-or-so next month. If it's on the way, drinks can be on me."

"It's not technically on the way, but it's worth a detour for a drink." Ronan said yes without hesitation, "Sounds like a plan. I'll come to see you next month with your birthday gift and some funny stories then. Happy birthday."

The red light counted down to three seconds. Victor put his hand on the end call button, "See you next month."]],
        music = "60_Beaytiful_Daily"
      }
    },
