        beijing = "Bg/2250.png",
        sentence = [[
"Many have been debating about LFG's intention behind investing in TK Healthcare. Everyone thought you were planning to get your foot in the medical industry. No one expected that your aim was to start a medical foundation with them. What an admirable surprise." In the studio, the host of the financial magazine in a suit smiled at Victor, "Someone posted in the comment section saying he was very proud to be a shareholder of LFG."

Victor gave a faint smile, "Thank you. LFG has received so much attention and support since it was founded, it is only natural to give back to society and take social responsibility as best as we can. We have done far from enough compared to enterprises that improve society and people's lives."]],
        music = "19_Daily02"
      },
      [2] = {
        extrastory_title = "On The Cover",
        beijing = "Bg/2250.png",
        sentence = [[
"Is your birthday coming up? If I remember correctly, you're the youngest person on the cover of our magazine since we started thirty years ago. I had the privilege of receiving the behind the scenes of the photoshoot from the director just now. I must say, you look incredibly dashing. I wonder if Mr. Victor... had any special plans for your upcoming birthday?"

The host emphasized "special", hoping he could share some exclusive information with the audience to boost the show's ratings. But Victor just leaned closer to the microphone and took out his phone, "Nothing special other than a lot of work to deal with that day. I'm afraid I don't have time to celebrate my birthday. Perhaps I'll cook myself a nice meal after work."]],
        music = "19_Daily02"
      },
      [3] = {
        extrastory_title = "On The Cover",
        beijing = "Bg/2250.png",
        sentence = "\"So you're not only a talented investor but also a gifted cook—I look forward to seeing LFG thrive under the leadership of such a dedicated helmsman. I bet the company's wide recognition and booming stock price today are the best birthday gift you give yourself. Thank you for coming today, Mr. Victor. On behalf of Wise magazine, I wish you a very happy birthday in advance.\"\n\"Build a life with financial knowledge. Follow Wise's social media account to get first-hand financial news...\"\n\nIn the airport lounge, Victor reached for the remote control to turn off the TV, noises vanished in the spacious semi-open private room. He laid the magazine open on his knees and took a quick glance at the content. The bold headline was eye-catching — LFG and TK Healthcare will Sign Strategic Investment Agreement in Three Days.",
        music = "19_Daily02"
      },
      [4] = {
        extrastory_title = "On The Cover",
        beijing = "Bg/2250.png",
        sentence = [[
