The flight attendant turned her gaze to him as she guided him down the stairs, "Mr. Victor, on behalf of the flight crew of Loveland Air, I hope you have a lovely birthday tomorrow. We have prepared a special meal and cake for you on board. Do you have any preference or dietary requirements?"]],
