    [2005] = {
      [1] = {
        extrastory_title = "Medical Fund",
        beijing = "Bg/1304.png",
        sentence = [[
The top floor of Camellia Hotel had a 360-degree view window, overlooking the lights of the entire city, and the starlight over head seemed to be in reaching distance. Victor sat in the hot tub, casually combed his wet fringe back with his hand and leaned on the massage jets on the back. Steam clouded the bottom as streams of water gushed out.

The red wine in his hand was at its best. He slightly shook the wine glass and took a sip before casting his eyes back to the boundless night view on his right.

At a distance was the TK Healthcare building opposite him. Overlooking from this angle, the building resembled a gate between heaven and earth, straddling life and death.]],
        music = "11_Sorrow_LongEnding_Ver"
      },
      [2] = {
        extrastory_title = "Medical Fund",
        beijing = "Bg/1304.png",
        sentence = "He turned to put down his glass before flipping through the minutes on the counter.\n\nLFG Medical Foundation, jointly funded by LFG and TK Healthcare for drug research and treatments—especially the latest drug for brain tumors which TK Healthcare announced to have entered the clinical stage six months ago. If the research goes well, this could be a breakthrough in defeating brain tumors.\n\nFrom equity investment to fund allocation, and from using LFG's name to recruit top medical teams, to cooperating with major hospitals... he hadn't rested for a second. Victor picked up the wine glass once again to down the whole glass before letting out a long breath.",
        music = "11_Sorrow_LongEnding_Ver"
      },
      [3] = {
        extrastory_title = "Medical Fund",
        beijing = "Bg/1304.png",
        sentence = [[
He remembered the case he had seen a year ago at a meeting in TK Healthcare.

The 32-year-old female patient went blind after her condition deteriorated. She bought her son, who had just turned five, a new pair of shoes for his birthday, but couldn't help him tie his laces. The people from TK Healthcare said that she was the most compliant patient, willing to put up with whatever side effects the medication would bring, yet she was a long way from recovering.

The whole conference room fell into silence.]],
        music = "11_Sorrow_LongEnding_Ver"
      },
      [4] = {
        extrastory_title = "Medical Fund",
        beijing = "Bg/1304.png",
        sentence = [[
