He still remembered every single detail.

The steam slowly climbed up the bathroom window, shutting out the night scene with a hazy mist.]],
        music = "11_Sorrow_LongEnding_Ver"
      },
      [5] = {
        extrastory_title = "Medical Fund",
        beijing = "Bg/1304.png",
        sentence = [[
Victor's gaze rested on the case on the minutes. After a whole year, all the indicators showed that her condition had improved. There was no knowing how much more medicine she would have to take and how much more she had to suffer, but at least now it seemed that she could celebrate her child's sixth birthday. Her doctor said given that all went well, she could last at least another five years. And who knew if another miracle might await in five years' time?

"Happy birthday."]],
