    [2006] = {
      [1] = {
        extrastory_title = "28 Years Old",
        beijing = "Bg/2331.png",
        sentence = "7:30 am. Victor checked his email habitually and saw the email received at midnight at a glance. He opened it with a smile as his eyes rested on the first line: Dear Vic, happy birthday.\n\nA letter from the past, from his mother's email.\n\nHe had no idea how many emails she wrote, saved, and scheduled before she passed away—The email system at that time wasn't as advanced and could only be scheduled for up to one year. So Victor's father logged into her email from time to time to schedule the emails to ensure that the emails could be sent in time.",
        music = "30_WarmSnow"
      },
      [2] = {
        extrastory_title = "28 Years Old",
        beijing = "Bg/2331.png",
        sentence = [[
She said it was a surprise, but it wouldn't be if he received it every year, which was why the last time he received birthday wishes from his mother was three years ago.

He read on.

Each of her letters was handwritten and then scanned into the computer. He could imagine her demeanor and tone from the handwriting of each letter.]],
        music = "30_WarmSnow"
      },
      [3] = {
        extrastory_title = "28 Years Old",
        beijing = "Bg/2331.png",
        sentence = "She wrote: Vic, it should be your 28th birthday today. Happy birthday. People start to stop celebrating their birthdays with their parents when they grow up. I wonder if you will be busy working or spending time with your girlfriend today. Twenty-eight years ago today, Mom brought you into this world, hoping you would have a worry-free life, and be the happiest, happiest child in this world.",
        music = "30_WarmSnow"
      },
      [4] = {
        extrastory_title = "28 Years Old",
        beijing = "Bg/2331.png",
        sentence = "I remember one time when you were little, you saw some toys you liked in a shop. Daddy said you had enough toys already, so you nodded understandingly and pulled us away. But I refused, and bought you all the toys from the shop behind your father's back. I don't need you to be mature, well-behaved, and obedient. I just want you to be happy. For Mom, preparing these letters for you one by one and imagining how you will feel when you receive them gives me a subtle sense of joy, as if I could cross the barrier of time and be with you every birthday.",
        music = "30_WarmSnow"
      },
      [5] = {
        extrastory_title = "28 Years Old",
        beijing = "Bg/2331.png",
        sentence = [[
Funny, isn't it? This was meant to be a gift to make you happy, but preparing this surprise seems to make me the happier one.

But what gift would the 28-year-old Vic want?

......]],
        music = "30_WarmSnow"
      },
      [6] = {
        extrastory_title = "28 Years Old",
        beijing = "Bg/2331.png",
        sentence = [[
Victor scrolled down the email and found a hand-drawn and colored amusement park ticket below.

She wrote, "Keep being fun even when you're an adult." Followed a line of small handwriting at the back in brackets, which read: It's okay not to be fun, as long as you're happy.

Happy 28th birthday.]],
        music = "30_WarmSnow"
      },
      [7] = {
        extrastory_title = "28 Years Old",
        beijing = "Bg/2331.png",
        sentence = [[
The whole email only consisted of a few hundred words, yet Victor spent a whole hour reading it.

He printed out the ticket, put it in his pocket, and got changed before he headed out to the amusement park.]],
        music = "30_WarmSnow"
      },
      [8] = {
        extrastory_title = "28 Years Old",
        beijing = "Bg/9061.png",
        sentence = "Today is Friday. The amusement park isn't very busy on a weekday, but the cheerful music was enough to make one leap. Victor strolled along and finally stopped in front of a facility.\n\nThe staff was guiding the queue to head inside. After a slight hesitation, he walked in and sat on the closest seat. The staff in an adorable fat doll costumes came over, greeted him with a bow, buckled his seat belt, and solemnly pointed his fingers to the blue sky, \"The great adventure is about to begin—Ladies and gentlemen, prepare to set sail into the sky! \"",
        music = "30_WarmSnow"
      },
      [9] = {
        extrastory_title = "28 Years Old",
        beijing = "Bg/9061.png",
        sentence = "Victor was slightly surprised. Then a jingling tune rang out, while the cheerful chortle of a little girl came from behind, \"Take off—Let's go—\"\n\nThe flying device rocked up and down, climbing to the highest point, when the breeze gushed to his face, brushing the hair on his forehead.\n\nVictor couldn't help letting out a laugh. With his fingers pressed to his pocket, he felt like he could touch the neatly folded hand-drawn tickets inside.\n\n\"I'll be very happy.\"\n\nHe held out his hand to the sky.",
        music = "30_WarmSnow"
      }
