        extrastory_title = "Being \"Mature\"",
        beijing = "Bg/1221.png",
        sentence = [[
Shaw went home and changed into something formal. He stood in front of the mirror and hastily tried to tame his hair before heading out to Loveland University.

There was an important discussion meeting at the school this afternoon that all students and teachers were required to attend. Although Shaw had another job in mind as he arrived at Professor Shear's office and knocked on the door slightly.

"Come in."

Professor Shear raised his head from behind a stack of papers. His eyes lit up as he saw Shaw.

"Looking sharp there!"]],
        music = "52_Daily03"
      },
      [2] = {
        extrastory_title = "Being \"Mature\"",
        beijing = "Bg/1221.png",
        sentence = [[
He glanced over Shaw's outfit, evidentially pleased that Shaw was finally wearing something that fitted a student rather than his old studded punk outfit.

"You came at the perfect time. After you received that scholarship for artistic excellence, a few of my colleagues wanted me to give you these books. They wanted me to tell you that they have great expectations for you."

Shaw looked at where Professor Shear was pointing and spotted two boxes filled with books sitting in the corner.

"That's a lot!"]],
        music = "52_Daily03"
      },
      [3] = {
        extrastory_title = "Being \"Mature\"",
        beijing = "Bg/1221.png",
        sentence = [[
Professor Shear patted his back and continued. "You should really be grateful. That scholarship is the cream of the crop amongst any young aspiring archaeology majors. Do you have any ideas how many eyes are on you right now? I got quite a few phone calls already from some really prestigious schools. They were asking if you have any intentions to continue furthering your education in the future."

The last sentence was very obviously a tentative question.

Shaw smiled thoughtfully, "I just started my Master's, and that's not something that has crossed my mind for now."]],
        music = "52_Daily03"
      },
      [4] = {
        extrastory_title = "Being \"Mature\"",
        beijing = "Bg/1221.png",
        sentence = [[
Despite hoping that such a prestigious student would stay in this uni, Professor Shear knew that Shaw was a young man that only acted on his own accord. He simply smiled and waved his hand.

"As long as you have something in mind already. Remember to come to the speech this afternoon on time." He paused as if remembering something, "I saved those seats you asked for earlier. When will your friends be coming?"

Shaw's expression froze briefly before smiling again, "they won't be coming."]],
        music = "52_Daily03"
      },
      [5] = {
        extrastory_title = "Being \"Mature\"",
        beijing = "Bg/1221.png",
        sentence = [[
"Relationship with people is sometimes a complicated thing." Immediately sensing abnormality in his tone, Professor Shear spoke with care and guidance in his voice, "You need to spend time to listen and understand when dealing with those problems, and that is a sign of true maturity."

"I understand."

Professor Shear nodded approvingly.

"But I think I'll still do things my way. I'm still young, after all. If I acted like what you just said, I would only be faking being mature."]],
        music = "52_Daily03"
      },
      [6] = {
        extrastory_title = "Being \"Mature\"",
        beijing = "Bg/1221.png",
        sentence = [[
