    [2204] = {
      [1] = {
        extrastory_title = "The Speech",
        beijing = "Bg/1391.png",
        sentence = [[
Inside Loveland University's great hall, the National Archaeology Conference was being held.

In front of the podium sat a cohort of the most authoritative archaeology professors and experts. The students sat squarely behind them, passing short and nervous glances at the panel of experts in front of them.

Shaw peeked through the veil and spotted Professor Shear. There were four empty seats behind him sticking out like a sore thumb.]],
        music = "60_Beaytiful_Daily"
      },
      [2] = {
        extrastory_title = "The Speech",
        beijing = "Bg/1391.png",
        sentence = [[
Shaw hesitated as he pondered.

After a while, he took out his phone and scrolled down on his contacts until he found Adam. But before he could do anything, a voice called out to him.

"Hey, you're up."

Shaw frowned and turned off his phone.]],
        music = "60_Beaytiful_Daily"
      },
      [3] = {
        extrastory_title = "The Speech",
        beijing = "Bg/1391.png",
        sentence = [[
"Please welcome the winner of the Archaeology Scholarship, and the student representative for academic excellence, Shaw!"

Shaw walked onto the podium accompanied by thunderous applause.

A confident smile was clearly visible on his face.

Shaw was never interested in the scholarship initially, until Professor Shear called him to his office and handed him another scholarship application form.]],
        music = "60_Beaytiful_Daily"
      },
      [4] = {
        extrastory_title = "The Speech",
        beijing = "Bg/1391.png",
        sentence = [[
"Professor, I told you I am not interested."

"I vaguely remember you saying you wanted to get some practical experience in the field." Shaw's expression loosened. Seeing that he has piqued his interest, Professor Shear continued. "As you know, most students must wait until summer, but since one of the scholarship's prerequisites is field experience..."

Professor Shear looked at Shaw thoughtfully. He had long understood Shaw's character. He might look lazy and unfocused on the surface, but that's because there was a lack of things that truly piqued his interest.]],
        music = "60_Beaytiful_Daily"
      },
      [5] = {
        extrastory_title = "The Speech",
        beijing = "Bg/1391.png",
        sentence = [[
As he expected, Shaw's eyes lit up.

"When is the deadline?"

Afterward, Shaw got his wish. He spent a month in the field in preparation for his application essay. His bandmates were surprised to hear that he participated in a school activity, let alone with such enthusiasm. They asked him a few times, but to their surprise, Shaw was far from feeling fatigued. On the contrary, he was practically radiating with energy.]],
        music = "60_Beaytiful_Daily"
      },
      [6] = {
        extrastory_title = "The Speech",
        beijing = "Bg/1391.png",
        sentence = [[
Time flies when you're having fun.

A month had slipped by without Shaw even noticing.

Despite Professor Shear's constant reminders, Shaw didn't care much about whether he won or not. He had already received the result he wanted. For him, it was a moment of actualizing joy.

Just like how time seemed to speed up when he was brushing away layers of soil from the artifact, or when he was completely fixated on a tough subject.]],
        music = "60_Beaytiful_Daily"
      },
      [7] = {
        extrastory_title = "The Speech",
        beijing = "Bg/1391.png",
        sentence = [[
The fruition of his hard work was equally as satisfying as the journey to get there.

Shaw recollected his thoughts and glanced over his audience below.

He smiled and took a deep bow as he dragged the microphone, letting out sharp feedback.]],
        music = "60_Beaytiful_Daily"
      },
      [8] = {
        extrastory_title = "The Speech",
        beijing = "Bg/1391.png",
        sentence = [[
Everything went according to plan.

After the conference, Professor Shear introduced Shaw to the panel of professors and experts as they showered Shaw with praises. Next, Professor Shear suggested they take a photo together, but Shaw couldn't help but shake the feeling that something was missing.

"Sir, do you know what time it is right now?"

"Getting close to six. What's wrong?"

Shaw paused for a bit. Then, his gaze became firm as he took a bow toward the professors.

"There's something I have to do. Please excuse me."]],
        music = "60_Beaytiful_Daily"
      }
