Lucien gazed in the distance and felt the gentle ocean breeze brush up against him. The ancient city stood solemnly against the nightly canvas in the background. The ornate and opulent buildings perfectly reflected the flourishing Baroquism popular at the time. Still, he was never quite a fan of that style of architecture.]],
        music = "13_Mail_tone_off"
      },
      [7] = {
        extrastory_title = "50 Minutes of Eternity",
        beijing = "Bg/3025.png",
        sentence = [[
