There was a small tremor beneath his feet. It was a moment when he felt his heartbeat become clearly audible. For some unexplainable reason, his thoughts drifted back to the memorable fifty minutes.

Or, he could stay a bit longer.]],
        music = "13_Mail_tone_off"
      }
