But in Lucien's eyes, it was nothing more than just an ordinary trumpet.

He turned around and walked out of the display room, the heavy wooden door slowly creaking shut behind him. The gentle night breeze brushed up against his forehead. "Perhaps I really should go back," he thought to himself again.]],
        music = "04_Normal"
