      [4] = {
        extrastory_title = "Sound of the Cosmos",
        beijing = "Bg/2392.png",
        sentence = [[
A silhouette not far from him caught his glimpse; it was the old trumpet player from earlier. He wobbled slightly as he walked down the road in a skip. His hands were outstretched like he was holding an invisible trumpet, his fingers dancing gracefully up and down as his head bobbed gently back and forth to the imaginary rhythm.

Bemused, children on the road began to follow him in imitation. The night was silent, yet Lucien could swear he heard something.

He raised his head as the leaves rustled under the serene moonlight. Gentle ocean breezes brushed up against the small crowd. The children made snorted chuckles as they laughed through the tiny crevices between their fingers.]],
        music = "04_Normal"
      },
      [5] = {
        extrastory_title = "Sound of the Cosmos",
        beijing = "Bg/2392.png",
        sentence = [[
