      [8] = {
        extrastory_title = "Peer Competition",
        beijing = "Bg/1221.png",
        sentence = [[
"Granted, on the surface, businesses are mostly concerned with the rise or fall of their assets, but is that all they bring? To me, businesses drive innovation and obsolesce inefficiencies. As they compete, they enable society to modernize as they lay the pioneering bedrock for advancements and fuel the engine of change for society. Is this not the positivity that you desire?"

