      [4] = {
        extrastory_title = "Emerging Talent",
        beijing = "Bg/2391.png",
        sentence = "\"I did hear of that, but do you seriously want me to audition for the role when I haven't even read the script yet?\" Kiro had hardly finished his sentence when the wig was quickly pulled down over his head.\n\n\"We don't have time to think that much about it. Just give it a try and see what happens.\"\n\nAfter doing his hair, Savin helped him put on the armor piece by piece, and then Mr. Harval, who had been sitting on his wooden chair all along, slowly said, \"I remember you saying that your childhood dream was to become a superhero. Well, let me tell you something. Sun Ce is a hero as well, so it doesn't matter that you don't know anything about him. Just remember, he's a dauntless hero, and you'll do just fine.\"\n\nKiro replayed those words in his mind over and over again until he got onto the set with Savin, where the director improvised an audition subject—",
