        beijing = "Bg/4781.png",
        sentence = "He got the role of Sun Ce. Apart from numerous congratulations, he also heard some doubts—\n\n\"A mixed-race guy with golden hair and blue eyes playing a famous historical figure of the East? Is there something fishy afoot?\"\n\nIt would be a lie if Kiro said he didn't care, but he also knew very well how different he was from Sun Ce. He began to visit the library frequently and borrowed one history book after another, only to find the words in them concise and abstruse. He asked Savin, and was told that it was a classical style of writing. They were articles written in archaic literary language.\n\nHe had no choice but to borrow an archaic language dictionary to look up the words one by one. Over time, he found himself rotating his head and speaking to a bottle of cola as tall as him in his dream—",
