        beijing = "Bg/3030.png",
        sentence = [[
Shaw was walking along a pathway on the side at a leisurely pace, the wires of his earphones swaying back and forth. Not until a fork came into view did he finally lift his eyes to glance left and right.

To his left, the winding pathway was extending forward, with several cars parked beside it.

To his right was a gentle slope inclining upwards. Through the gaps between trees, he could see tombstones standing here and there, along with several clouds of white smoke wafting from burning sacrificial items.

This was his second time coming here since he'd given the old man a burial. It had been almost a year, and he was surprised to see how many more tombs had been set up. He could hardly locate the old man's resting place.

But Shaw was in no hurry. He dug his hands into his pockets and headed east without hesitation. No matter how much this place had changed, he couldn't miss his destination if he headed for the most geomantically propitious spot.]],
        music = "30_WarmSnow"
      },
      [2] = {
        extrastory_title = "One-Sided Conversation",
        beijing = "Bg/3030.png",
        sentence = [[
