"Hey, old man."
"This photo I picked for you turns out to be pretty good. You're the one with the happiest smile around here."

Shaw raised his hand to flick the withered leaves off the tombstone, but after only a few seconds, his hand was covered in dust.

"..."

After a moment of silence, he clenched the white cuff of his sleeve and began to clean the grime over the gravestone bit by bit.]],
        music = "30_WarmSnow"
      },
      [3] = {
        extrastory_title = "One-Sided Conversation",
        beijing = "Bg/3030.png",
        sentence = [[
