After saying that, Shaw suddenly narrowed his eyes and sneezed aloud several times in a row.

"...You just couldn't wait to curse me."
"Well, calm down a little. I haven't finished my report yet. You may throw all your curses at me when I'm done."

A patch of his right sleeve was black now, so Shaw clenched the other cuff of his sleeve and resumed the wipe.

"Originally, I planned to wait until Tomb-Sweeping Day to do this. Some rules must be followed, you know, even though I can't come here often."]],
        music = "30_WarmSnow"
      },
      [4] = {
        extrastory_title = "One-Sided Conversation",
        beijing = "Bg/3030.png",
        sentence = "\"But I'll have some business to attend to at school that day, so I decided to come ahead of schedule.\"\n\n\"As for the antique store... everything's fine, except that we got a lot fewer customers due to your absence.\"\n\n\"As you know, I'm not the hard-working type, so I'll just do my best to make ends meet for you. Oh, there's another thing—\"\n\n\"Days ago, I accidentally broke a cup of yours. Fortunately, it was just a Qing Dynasty item, and I did some timely restoration, so the loss was minor. I just feel guilty about failing to protect your stuff, so please allow me to apologize.\"\n\nShaw lifted the plastic bag he had carried all the way to the tomb, swayed it before the headstone, and pulled out a still-warm roast chicken, a few fruits, and a handful of plain sunflower seeds.",
        music = "30_WarmSnow"
      },
      [5] = {
        extrastory_title = "One-Sided Conversation",
        beijing = "Bg/3030.png",
        sentence = [[
