        beijing = "Bg/3030.png",
        sentence = "\"Old man, if I perform divination here, will I be able to figure out what you want to say to me?\"\n\nClink—\n\nThe tossed copper coins fell to the ground and were scattered. Shaw bent over, took a look, and smiled.\n\n\"Incredible. It really worked.\"\nHe glanced at the wine cup, which was only half full, then picked up the bottle of liquor and filled the cup to the brim.\n\n\"Alright, I've filled your cup, but don't drink too much. I've really got to go now. I'll visit you again when I have time.\"",
