      [3] = {
        extrastory_title = "That Chatty Old Man",
        beijing = "Bg/1761.png",
        sentence = "Seeing that the parrot continued fluttering its wings, he speechlessly picked up the basin on the side and headed towards the door.\n\n\"Alright. That's a very precious voice you got there. I've been keeping you for five years or so and hardly heard you speak.\"\n\nWith that, he lifted the basin and poured out the water—\n\"Hey, I can hardly say this is a coincidence. You little rascal, you aimed that right at me, didn't you?!\"\n\nUpon entering the antique store, Yen narrowly escaped getting drenched. His feet felt like they'd touched an electric current as he jumped onto the dry tiles, trembling.\n\nShaw just gave a shrug and mopped up the water on the floor. \"You said it yourself; it's a coincidence, so stop complaining.\"",
        music = "48_Quiet_Daily"
