      [5] = {
        extrastory_title = "That Chatty Old Man",
        beijing = "Bg/1761.png",
        sentence = "Yen subconsciously halted, looked back, and paled visibly.\n\"Thi–This is a masterpiece by Huang Tingjian. How could you put it here?\"\n\n\"The long rainy period is finally over, and it's not every day you get such dry cloudy weather, so I placed it here to air it out.\"\n\nHis body was still tense, as if he hadn't yet recovered from the fright he'd been through. \"You should've at least put it somewhere safe. I almost stepped on it!\"\n\nShaw silently put his mop down, still impassive.\n\"Yen, when his work was created, it didn't know it'd be preserved for hundreds of years or that it'd be trapped in a wooden casket by subsequent generations.\"",
        music = "48_Quiet_Daily"
      },
      [6] = {
        extrastory_title = "That Chatty Old Man",
        beijing = "Bg/1761.png",
        sentence = [[
