How had the light of this thing brought him here?

He stared in bemusement at the Dragonfly Eye in his hand for a while but couldn't make a head or tail of it. His gut told him that there was definitely a secret hidden within. But the old man had never told him anything about it except that he must keep it safe...

He was pondering when the sound of a flurry came from the side chamber. Shaw immediately came to himself and tiptoed in that direction. On reaching the entrance of the side chamber, he spotted an old-fashioned flashlight overturned on the ground. Looking where the light was pointing, he saw a young man dressed in a crumpled Chinese tunic suit whose leg was stuck fast beneath a broken slate.]],
        music = "08_Tension"
