      [7] = {
        extrastory_title = "Dazzling Light",
        beijing = "Bg/1811.png",
        sentence = "Shaw stayed where he was and watched as the strange young man wriggled around on the ground, grimacing and sweating buckets.\n\nAfter he finally managed to pull his leg out of the crevice and struggled to his feet, he lifted his head, saw Shaw standing in the doorway, and nearly slumped to the ground again out of horror.\n\n\"Wh–Who are you?\"",
