As the young man squinted his eyes due to the glare, Shaw knitted his brows.

The square-faced man looked a bit familiar.

But the next second, the young man blocked the glare with his hand. Seeing him remain silent for a while, Shaw shifted the light onto the man's hand and flicked his flashlight.]],
        music = "09_Suspect"
      },
      [2] = {
        extrastory_title = "Familiar Square Face",
        beijing = "Bg/1811.png",
        sentence = "\"Don't play dumb with me. That jade bead is the treasure you want to steal, right?\"\n\"Here's the deal. I'll give you a chance to atone for your crime. Give it to me, and I'll hand it in for you.\"\n\nThe young man instantly hid the perfectly round white jade bead in his hand behind his back, his face full of indignation.\n\n\"Wha–What do you take me for? Handing it over to the government has always been my plan. This is archaic calcified jade. It's a cultural relic dating back to the Western Han Dynasty. There's no way I'm giving it to a stranger like you!\"\n\n\"I can tell from your hair that you're no good. You might be in cahoots with those thieves!\"",
        music = "09_Suspect"
      },
      [3] = {
        extrastory_title = "Familiar Square Face",
        beijing = "Bg/1811.png",
        sentence = [[
Shaw was amused by those words and ran his fingers through his bluish-purple hair.
"Impressive. You're pretty savvy, not an utter ignoramus. But you're wrong about one thing. This place wasn't built in the Western Han Dynasty. It dates back to the Ming Dynasty at the earliest."

While speaking, Shaw shone the flashlight onto the bulky wooden chest behind the young man.

"This is gray sand, made from lime, glutinous rice, and grit. Nobody could produce it until the Ming Dynasty."

