      [5] = {
        extrastory_title = "Familiar Square Face",
        beijing = "Bg/1811.png",
        sentence = "The young man's face turned red, his voice becoming increasingly impassioned, and Shaw couldn't help laughing.\n\n\"I finally remember who you resemble. Your accent, your tone of voice, and your face that can't be any more square...\"\n\n\"The spitting image of an old man I know.\"\n\nShaw looked the young man up and down again. \"It's okay if you prefer a retro style, but your face doesn't go well with it. Too frumpy. You might want to put your slicked-back hair down...\"\n\nHe hadn't finished speaking yet when another dazzling light burst forth before his chest—",
        music = "09_Suspect"
