    [3105] = {
      [1] = {
        extrastory_title = "Picture of Changes",
        beijing = "Bg/2255.png",
        sentence = "In the following week, Shaw scoured the antique store but couldn't find any information about the Glaze Dragonfly Eye.\n\nAfter a long silence, he finally lifted his hand, pushed the switch behind the curio shelf, and walked into the secret room. By the light of the kerosene lamp in his hand, he wordlessly gazed at everything in front of him—an ancient codex fell open on the wooden table at the far end, a magnifier reposing at its corner, and a chair facing the door diagonally.\n\nThis place was overlaid with \"traces\" left by the old man when he'd last been here.\n\nThat was why he tended not to visit this place.",
        music = "30_WarmSnow"
      },
      [2] = {
        extrastory_title = "Picture of Changes",
        beijing = "Bg/2255.png",
        sentence = "He did not know whether he should tidy up this messy secret room or keep it the way it was.\n\nHe could not shake the feeling that straightening these things up would grant time a chance to efface all the traces they bore. Therefore, he intentionally avoided many things when rummaging through the room.\n\nThe kerosene lamp began to dim, but his search remained fruitless. His only unexpected discovery was a grimy wooden chest he dragged out of the bottom compartment of the curio shelf—\n\nIn it were a red, hard-covered photo album and some knickknacks.\n\nShaw opened it to the first page without thinking.",
        music = "30_WarmSnow"
      },
      [3] = {
        extrastory_title = "Picture of Changes",
        beijing = "Bg/2255.png",
        sentence = "He was greeted by the sight of four group pictures, in each of which were seven or eight young men, all wearing tunic suits and smiling bashfully.\n\nThe next second, Shaw's fingers holding the album tightened slightly somewhat—\n\nIn the picture, standing at the rightmost was a square-faced young man with slicked-back hair.\n\n\"...\"\n\nHe held his breath, despite himself.\n\nThe answer to his guess was staring at him in the face, but he still unseeingly moved to the next page.",
        music = "30_WarmSnow"
      },
      [4] = {
        extrastory_title = "Picture of Changes",
        beijing = "Bg/2255.png",
        sentence = "There weren't many pictures of that man, but they showed the slow changes he had undergone over time—he became fairly corpulent, with more wrinkles and hoary hair.\n\nEventually, the man became the person he could not be more familiar with.\n\n\"...\"\n\nWhen everything became indisputable, Shaw smiled despite himself, but there was a ghost of unnoticeable regret in his eyes.\n\n\"...Old man, you're fun. You kept so many secrets from me... But it might not be a bad thing. I'll just take it as a mystery I got to unravel.\"",
        music = "30_WarmSnow"
      },
      [5] = {
        extrastory_title = "Picture of Changes",
        beijing = "Bg/2255.png",
        sentence = "\"Sooner or later, I'll find out whether that man was a hallucination of mine or I really met you.\"\n\nWhen he put the photo album back, he discovered a yellowed notebook underneath.\n\n\"You got a lot of stuff here.\"\n\nShaw leafed through a few pages. The contents were the old man's notes about ancient relics, made when he was young, along with some desultory essays—\n\n\"History isn't as distant as we imagine. All you need to do is touch it to become a part of it.\"",
        music = "30_WarmSnow"
      },
      [6] = {
        extrastory_title = "Picture of Changes",
        beijing = "Bg/2255.png",
        sentence = [[
After reading those words, Shaw inadvertently shifted his gaze to the ancient codices and calligraphy works.
For some reason, these things, which he had frequently seen all his life, seemed to change somewhat at this moment.

It was like, he could see through these things to the past, to a former life.
With that in mind, he lifted his hand and placed it on one of the ancient codices.

Had he become a part of history?
If he were to be honest, he had doubts, but there was nothing he could do.
Because the only one he could ask had become "history."]],
        music = "30_WarmSnow"
      }
    },
    [3106] = {
      [1] = {
        extrastory_title = "Good Disciple",
        beijing = "Bg/1761.png",
        sentence = "The Summer Solstice came unannounced, and the cicadas cried louder.\n\nWhen Shaw bent to pull up the roller shutter of the antique store, a ding came from inside his pocket.\n\nHe patted the dust off his hands before checking the message—\nSpeedy Skateboard Store: Dear member, happy birthday! Coupons are sent to your account. Feel free to come and make purchases! Reply with STOP to unsubscribe.\n\nShaw texted back STOP without hesitation and walked straight into the store.\nHalf of this year had passed, and it was about time to do the bookkeeping. No matter how unwilling he was to deal with business, some basic matters must be handled.",
        music = "804_LX_Birthday_2023"
      },
      [2] = {
        extrastory_title = "Good Disciple",
        beijing = "Bg/1761.png",
        sentence = [[
