He ripped it off, took a look at it, and found that it was not only crumpled but also had many pictures of cakes printed on it, one of which was Longevity Peach Cake.

Shaw couldn't help snickering at the sight of it.

"Old man, you're not insinuating anything with this, right?"

However, the only response he received was the chirps of cicadas.

But Shaw didn't mind, his smile broadening.]],
        music = "804_LX_Birthday_2023"
