Before long, a middle-aged woman with a northern accent answered his call, "Mr. Hua, what took you so long? Don't you usually place an order several days in advance? But no worries, I've gotten the cake ready for you."

"So when are you coming to pick it up? I'm about to close the store."

Shaw clenched the receiver, "Now."]],
        music = "25_Romantic_Quiet_MAS"
