        beijing = "Bg/1761.png",
        sentence = "\"You little brat! You little rascal!\"\n\nAt that moment, as if a stone had been tossed into the quiet lake, Shaw abruptly straightened his back and looked at the parrot, who finally spoke. The street was still encased by the darkness of night, but Shaw felt as though time was being reversed, and he actually heard the din of the day—\n\n\"Old man, will you please stop nagging me so often? The parrot is learning to speak. I don't want a bird added to my list of scolders.\"\n\n\"I wouldn't have had to say that had you not caused me so much trouble, you little brat.\"\n\n\"...You old geezer.\"\n\n\"Pfui, you little rascal!\"",
