        extrastory_title = "Breaking Free From Despair",
        beijing = "Bg/2200.png",
        sentence = "It was the hottest time in July, but Gavin still couldn't master his own wind at will. Near August, the instructor took all the new recruits to an abandoned warehouse in the middle of the woods.\n\n\"Stay here for 15 hours and you pass the test. If you give up halfway, you fail and will be sent to an ordinary police academy.\"\n\nAfter the instructor left, Gavin was taking a look around the place when everything suddenly became dark.\n\n\"A blackout?\" He heard people whisper.\n\n—Something was wrong. He remembered the gate of the warehouse being old, with light usually seeping through the cracks. It shouldn't be engulfed in a smothering darkness like this..",
        music = "36_BC_Story"
      },
      [2] = {
        extrastory_title = "Breaking Free From Despair",
        beijing = "Bg/2200.png",
        sentence = [[
Slowly, he took a few steps back, and by the eighth step, he felt the wall and its peeling paint.

As time passed, he sensed the tension mounting around him, and his teammates' breath growing heavier. Irritation spread to his limbs in the leaden air.

Gradually, the noise trailed away, the putrid smell in the old warehouse fading with it.

Gavin bit the tip of his tongue, seeking some sensation of pain, but his body gave no response. He didn't even know if he had actually bitten down.

Dread and confusion seeped from his heart and pervaded his limbs.]],
        music = "36_BC_Story"
      },
      [3] = {
        extrastory_title = "Breaking Free From Despair",
        beijing = "Bg/2200.png",
        sentence = [[
How could 15 hours feel so interminable?

"You are not strong enough to protect anyone."

The man's scornful taunt echoed in his mind, mingling with the sea of fire that seemed to corner him in the endless dark.

"Is this your proof?"

In a fit of fury, he let out a primal yell and hurled his body against the wall, desperate to awaken from this torment. But neither pain nor sound greeted him.

"You did well. You are truly my son."]],
        music = "36_BC_Story"
      },
      [4] = {
        extrastory_title = "Breaking Free From Despair",
        beijing = "Bg/2200.png",
        sentence = "The man's voice sounded again. Stunned and speechless, Gavin saw the man's palm reach out, a strange look of approval on his stony face, \"It's enough.\"\n\nEnough?\n\nHe couldn't see himself but heard a gentle voice coming vaguely from somewhere far away.\n\n\"Gavin—\"\n\nWithout a second thought, He traced the voice. In a blurry memory, he saw his younger self standing by a river, drenched and smiling innocently at his mother. She shook her head helplessly and tapped his head.",
        music = "36_BC_Story"
      },
      [5] = {
        extrastory_title = "Breaking Free From Despair",
        beijing = "Bg/2200.png",
        sentence = "A warm breeze slowly surrounded him and blew his clothes dry.\nIn the next moment, the babbles of the river turned into a beautiful piano song. He opened his eyes while sitting on the rooftop and threw out a paper plane, which flew away in the wind along with the flowing notes.\n\nThump, thump—\nGavin seemed to feel his own heart pounding. It would start fluttering every time he heard the song.\n\nOne, two... It beat heavily and sturdily inside his chest.\nStrange images flashed across his mind. He seemed to see a girl standing not far from him in the high school library one afternoon, her eyes fixed on the book in her hands.\n\nHe yawned and clumsily flipped a page.",
        music = "303_Back_in_black"
      },
      [6] = {
        extrastory_title = "Breaking Free From Despair",
        beijing = "Bg/2200.png",
        sentence = [[
"No matter what the sky above is like, I'm ready for any storm."

The man's hand was still outstretched, but Gavin let out a laugh and threw his punch.
"Go away!"

A long time later, the creak of the gate opening sounded like an explosion in the silence.
The piano song was gone.

With the only strength he could gather, Gavin opened his eyes and heard only one sentence:

"Congratulations on passing the test."]],
        music = "303_Back_in_black"
      }
    },
    [3205] = {
      [1] = {
        extrastory_title = "Precious Power",
        beijing = "Bg/4526.png",
        sentence = [[
Only 12 students passed the test, and they began even harsher training after that.

Gavin fastened his supplies and parachute and stepped onto the transport plane. It was the first real parachuting after their simulation training. Unlike his usual self, Gavin felt a bit nervous.

Soon, the plane reached the designated altitude. As the wild wind outside the hatch blew into the cabin, he felt dazed and dizzy looking at the distant ground beneath, cold sweat in his palms.

With a command from the class leader, he suppressed his fear at that moment and jumped off the plane.]],
        music = "1007_Kingdom_of_This_World"
      },
      [2] = {
        extrastory_title = "Precious Power",
        beijing = "Bg/2243.png",
        sentence = [[
The wild wind blasted against him as he tried to find balance. With a whoosh, the parachute on his back was released and filled with air, slowing his descent.

Gavin let out a long breath and opened his eyes.

The silent magnificence of the endless mountains that sprawled beneath him blew him away.

He felt like a speck of dust floating in the sky, small yet free.

"Aaaah! Help!"
He suddenly heard a husky scream from above and then saw a familiar figure dropping rapidly in front of him. Realizing that the man's parachute hadn't been released properly, Gavin immediately yelled: "Lucas! Pull the backup lever!"]],
        music = "1007_Kingdom_of_This_World"
      },
      [3] = {
        extrastory_title = "Precious Power",
        beijing = "Bg/2243.png",
        sentence = [[
His voice was blown away in the rapid flow of air. Seeing that the man was descending further away, Gavin unfastened his own parachute and jumped down before he could think twice.

He was suddenly overcome by a sense of weightlessness. His Evol generated a gust of wind, allowing him to clumsily approach his classmate in the air. He tried to use the wind to lift the person up, but the force went against his will, throwing the man up high and then losing his balance again.

The figure floated up and down, close and far in the wind, slipping past his fingertips again and again.

Almost!
Gavin clenched his teeth.]],
        music = "1007_Kingdom_of_This_World"
      },
      [4] = {
        extrastory_title = "Precious Power",
        beijing = "Bg/2243.png",
        sentence = "He didn't know what his action meant, but there was one thing he knew—he couldn't let the man drop to the ground like this.\n\nThe gale and gravity pulled them down, but he still reached out his hand and furiously yelled at the power in his heart—\n\nPush him to me!\n\nFinally, he grabbed onto something and felt a heaviness dropping into his palms. He pulled to release his backup parachute and breathed out only when he felt the uniform through his gloves.\n\n\"Grab on!\"",
        music = "1007_Kingdom_of_This_World"
      },
      [5] = {
        extrastory_title = "Precious Power",
        beijing = "Bg/2243.png",
        sentence = [[
However, the wind that was out of control pushed them to a continuous spin in the air. The ropes twined in circles until the parachute lost balance and the weightlessness assaulted their senses again.

Their visions turned upside down as the wind brushed past them like blades. Gavin blacked out for a moment, but his body was still grabbing onto his teammate who was completely stunned.

He groped for the locks and unfastened his parachute soon. However, the lever of his teammate's backup parachute flapped violently out of his reach, and the wind carried them further away.

His heart pounding heavily, Gavin tried not to look at the ground and focused all his attention on the energy inside him.

"Gavin! Don't use your Evol! Stay in defense!"]],
        music = "1007_Kingdom_of_This_World"
      },
      [6] = {
        extrastory_title = "Precious Power",
        beijing = "Bg/3721.png",
        sentence = [[
The instructor's repeated shout reached his ear in the gaps of the wind. Almost by instinct, Gavin held his teammate in his arms and braced for impact.

The next moment, he felt his body falling into the woods, brushing past tree branches and steadily landing onto a wide softness before bouncing back up.
Gavin looked up at the leaves falling from the canopies and reached out to the "net" that caught them underneath.
Soft yet sturdy, it supported them both.

"The wind blew us too far off the target... The magnetic field here is jamming our signals. It is about to get dark, and the place is too steep. Let's stay put and wait for rescue."
The kind instructor was also in a mess. He patted Lucas who was trembling and weeping, "Go see the doctor when we get back. Let the therapist check you out."]],
        music = "18_Sorrow_love"
      },
      [7] = {
        extrastory_title = "Precious Power",
        beijing = "Bg/3721.png",
        sentence = [[
Gavin's senses slowly returned in the instructor's reassuring words and his teammate's loud weeps. He took a few steps and finally felt he was standing firmly on the ground.

The moment he fell from the sky, he felt as if his heartbeat had stopped.
He didn't know why he listened to the instructor, but at that moment, he trusted someone else with his life without hesitation.

A bottle of water and Principal Willis's face appeared before him.

"You were crazy, you know? You did well catching him, but the rest was only making things worse."

Instead of answering, Gavin took the water and gulped it down.]],
        music = "18_Sorrow_love"
      },
      [8] = {
        extrastory_title = "Precious Power",
        beijing = "Bg/3721.png",
        sentence = [[
