    [3206] = {
      [1] = {
        extrastory_title = "Among the Clouds",
        beijing = "Bg/2021.png",
        sentence = "The pale moon was hanging in the sky in a misty glow.\nGavin couldn't sleep. He felt as if the power inside him was awakening, spreading to every inch of his skin, like he was surrounded by his mother's breeze.\n\nIt seemed that his Evol was somehow different from before.\n\nHe looked at Lucas and the instructor in sound sleep and quietly took the backup parachute.\n\nThe twilight dyed the horizon pale purple. He stood on a precipice and gazed into the distance. The evening wind breezed in the mountains, surrounding him lovingly. He closed his eyes, remembering the feeling of falling from the sky yesterday—",
        music = "30_WarmSnow"
      },
      [2] = {
        extrastory_title = "Among the Clouds",
        beijing = "Bg/2021.png",
        sentence = "At that moment, something gushed out from deep inside him—a force so familiar yet strange, as if surging waves turned into a gurgling stream.\n\nAnother gust of wind blew by, as if calling upon him.\n\nHe took a deep breath and slowly leaned forward off the precipice—\n\nHe heard the sound of wind rushing by his ear but felt no longer anxiety but trust. He gave himself to it and felt lighter and lighter, the whoosh of air becoming soft, enveloping him in an invisible yet tight embrace.\n\nIt was like an invisible hand gently pulling him up to a higher place.",
        music = "30_WarmSnow"
      },
      [3] = {
        extrastory_title = "Among the Clouds",
        beijing = "Bg/2021.png",
        sentence = [[
He felt like a bird, and the moment he soared to the sky, the first ray of light from the eastern sky shone through the early morning mist and into his eyes, leaving a faint halo.

The world brightened up.

His eyes were wide open. The lush emerald mountains basked in the sunlight, as if it was waking up from a long slumber, cleansing the world of dust and dirt. The rivers and streams surged on, while a green blanket covered the vales and hills.

The world stood still, in silent serenity.

At that moment, the heaviness over his chest was also lifted by the wind.

He never knew the world was so huge.]],
        music = "408_BQ_Birthday_2023"
      },
      [4] = {
        extrastory_title = "Among the Clouds",
        beijing = "Bg/2021.png",
        sentence = "Cities, fields, and mountains all became large colorful patches. Those dark and cramped corners shrank into tiny dots. The narrow paths led to faraway lands.\n\nThe light breeze twirled around him and blew by the clouds. He waved his arm and made the cotton-like cluster into a big paper plane, ready to fly forward with the wind.\n\nHe spread his arms and let the wind carry him anywhere, as an endless view unfolded in his eyes.\n\n\"I—CAN—FLY—!\"\n\nThere was nothing to stop him.",
        music = "408_BQ_Birthday_2023"
      },
      [5] = {
        extrastory_title = "Among the Clouds",
        beijing = "Bg/2021.png",
        sentence = "His jovial and carefree laughter echoed in the sky. The wind in his palms blew wherever he willed, as though it could become the sharpest blade or the steadiest embrace.\n\nSuddenly, he thought of that afternoon from a long time ago—\n\nMaybe he had mistaken what his Evol meant to him. It was not only a power to make him stronger, but also his loved ones' best gift and blessing to him.\n\nAt this moment, the invisible wind was fully in his grasp at long last.\n\nThe sun slowly rose as he welcomed his eighteenth birthday.",
        music = "408_BQ_Birthday_2023"
      }
    }
  },
