      [3] = {
        extrastory_title = "A Prodigy's Self Discipline",
        beijing = "Bg/4834.png",
        sentence = [[
When Lucien first joined the lab four years ago, he spent his entire first year learning its inner workings. Outside of academic hours, he used the extra time to try and secure his own laboratory and access to other research data and resources. He was determined to unravel as many scientific mysteries as he could in his limited time in this world, just as he had told Dr. Lawson during his interview years ago.

While being ahead of time is indeed a delightful sensation, there were still far more important things in his sight.
Which is why he proposed to Dr. Lawson to shorten the duration of his graduate and Ph.D studies three years ago.]],
        music = "30_WarmSnow"
      },
      [4] = {
        extrastory_title = "A Prodigy's Self Discipline",
        beijing = "Bg/4834.png",
        sentence = [[
"Give me a valid reason," Dr. Lawson said, looking up from his report with his eyebrows slightly raised.

"I believe my current project and thesis are adequate enough to warrant a graduation in three years, four at the most."

His calm voice carried an air of youthful resolve. Dr. Lawson remained silent for a moment, pondering, then set aside his report.

"They say there are some interesting new stalls at the nearby market. Care to join me for a walk?" His words left little room for refusal.

After walking from one end of the market to the other, they both ended up carrying several paper bags.]],
        music = "30_WarmSnow"
      },
      [5] = {
        extrastory_title = "A Prodigy's Self Discipline",
        beijing = "Bg/4834.png",
        sentence = [[
"You seem to really enjoy this wine."

"The family has been making it for three generations, and I've known the current owner since he was a little boy," Dr. Lawson replied with a smile, fondly recalling his childhood days of grape picking at his grandparents' vineyard.

Lucien listened quietly as the professor retold his rich experiences, feeling somewhat overwhelmed as he struggled to find a reply. Thankfully, the conversation eventually returned to him.

"I respect your choice and trust in your judgment, Lucien."

"There's only so much you can learn in school. Even the most sound hypothesis requires practical applications to verify its validity. Besides, no one can tell you which path to undertake, we all have our own roads to walk."]],
        music = "30_WarmSnow"
      },
      [6] = {
