        sentence = [[
A week later, Lucien received an unexpected reply to his routine report email.

"3 PM, Charles River."

Lucien paused. The Black Swan Collective had rarely informed him of a meeting in the past two years, preferring more unexpected methods such as visiting his lab, "accidentally" running into him, or sending agents who were terrible at blending in to a party he was attending.

He never voiced his irritation on the matter as he felt it would be a terrible waste of his precious time.

