Lucien remembered buying the camera when the doctor had taken the entire lab to another school for an academic exchange. It was Christmastime, and the snow-covered streets were adorned with festive lights and a towering Christmas tree. Everyone else was slightly drunk, excitedly joining the celebrations, while he wandered into a second-hand antique shop. Amidst an array of cutlery, dolls, and furniture... his gaze settled on the camera perched on the shelf's edge.

