        sentence = "\"That's our show, kids! See you tomorrow!\"\nAs little Shaw finished the last bite of his birthday cake, the brightly dressed host on TV also waved his goodbyes. Cheerful music played as the screen faded to credits. Shaw knew what that meant: there'd be no more cartoons today.\nTomorrow.\nHis lips pouted involuntarily at the thought of that word. He was headed home tomorrow, and he didn't know if he'd still get to go on adventures with his friends inside the TV.\nThe images on the TV kept changing. After a few commercials, two suited adults suddenly came onto the screen and began reporting on the news—boring stuff that he didn't care about. He turned the volume down with the remote, and soon his grandmother's faint voice from the study drifted into the room.",
        music = "90_childrenday"
      },
      [2] = {
        extrastory_title = "Aspiring Wish",
        beijing = "Bg/3160.png",
        sentence = [[
"I'm just an old woman; don't worry about me..."
"He's been doing quite well these past days. It's you who should..."
"Shaw is still a kid. Why won't you let him..."
Hearing his name, Shaw immediately perked up his ears. Unfortunately, he couldn't make out the rest of the conversation. After a moment's hesitation, he quietly rose from his small stool and tiptoed toward the study.]],
        music = "90_childrenday"
      },
      [3] = {
        extrastory_title = "Aspiring Wish",
        beijing = "Bg/4509.png",
        sentence = [[
Grandma was on the phone. Her voice was deliberately quiet, yet Shaw could sense she wasn't pleased.
He had a vague idea who she was talking to, but curiosity still got the better of him. Unfortunately, just as he leaned toward the door, the old wooden floor creaked loudly beneath him. Grandma immediately looked over, her eyes meeting his directly.
Shaw's face flushed red instantly, and he turned to run away.
"What are you running for?" Grandma called softly, covering the phone receiver.
"I wasn't running," Shaw awkwardly touched his nose and turned back around. "I... I was just passing by to get something to eat."]],
        music = "90_childrenday"
      },
      [4] = {
        extrastory_title = "Aspiring Wish",
        beijing = "Bg/4509.png",
        sentence = [[
The kitchen wasn't anywhere near the study, but Grandma didn't point out his poor excuse. Instead, she smiled gently and extended the phone toward him. "Alright then. Shaw, would you like to speak on the phone?"
"No!" Shaw blurted out immediately. He wasn't stupid; he knew the call wouldn't bring anything pleasant, and he had no interest in listening.
Grandma was speechless for a brief moment, and after a few more polite exchanges on the phone, she hung up the phone. Shaw shuffled slowly toward her as Grandma reached out and gently placed her hand on his head, softly stroking his hair from his stubborn cowlick down to his stiff neck.]],
        music = "90_childrenday"
      },
      [5] = {
        extrastory_title = "Aspiring Wish",
        beijing = "Bg/4509.png",
        sentence = [[
After a long silence, Shaw finally mumbled, "...I don't want to answer the phone."
"Alright, you don't have to."
"...I don't want to go home either."
"Why not?"
"I'm not happy there."
Grandma let out a soft sigh, gently asking, "Then are you happy spending your birthday here at Grandma's?"
"Yes!" Shaw answered without hesitation. "Nobody tells me what to do here. I can watch cartoons and eat tasty food. It's perfect."
"Oh, you," Grandma chuckled lightly, gently pinching his cheeks. "But if nobody watches over you, you'll turn into a wild child."]],
        music = "90_childrenday"
      },
      [6] = {
        extrastory_title = "Aspiring Wish",
        beijing = "Bg/4509.png",
        sentence = [[
"No, I won't! I'm gonna grow up and turn into the Great Sage!" Shaw proudly lifted his head. "The Great Sage doesn't need supervision. He can go wherever he wants and do whatever he pleases."
Out of all the cartoon characters, the Great Sage was Shaw's favorite. Nobody could tell the Great Sage what to do or where to go; he only did and went where he pleased.
"You want to become the Great Sage?" Grandma asked with surprise.
"I don't want to be him," Shaw corrected seriously. "I am the Great Sage."]],
        music = "90_childrenday"
      },
      [7] = {
        extrastory_title = "Aspiring Wish",
        beijing = "Bg/4509.png",
        sentence = [[
"Oh, I see," Grandma smiled, dragging out the words playfully. But then she challenged him gently: "But didn't the Great Sage lose to Buddha? And didn't Monk Tang Sanzang bind him with a golden circlet during their journey to the West?"
"That's..." Shaw hesitated and then pouted stubbornly. "That's all made up! Hmph! In my heart, the Great Sage never lost!"
"Hahaha!" Grandma laughed, her eyes wide with delight.
Shaw became visibly flustered. "Why won't you believe me?"]],
        music = "90_childrenday"
      },
      [8] = {
        extrastory_title = "Aspiring Wish",
        beijing = "Bg/4509.png",
        sentence = "\"I do believe you, my little Shaw,\" Grandma chuckled, patting his head. \"But even if the Great Sage did lose from time to time, that doesn't make him any less great.\"\nShaw blinked, not quite understanding.\n\"Wanting to be strong and free is a good thing,\" Grandma said softly. Her words floated in the warm summer evening air, slow and deliberate. \"But even being trapped under a mountain for five hundred years, or having that golden circlet on his head, might not be such a bad thing.\"\n\"Because going through all that—only then does he truly understand what's worth holding onto.\"",
        music = "805_LX_Birthday_2024"
      },
      [9] = {
        extrastory_title = "Aspiring Wish",
        beijing = "Bg/4509.png",
        sentence = "Shaw looked at her. At six years old, he could vaguely sense that she was trying to comfort him. But he didn't want to understand. Losing to the Buddha? That was infuriating. Being trapped for five hundred years? Way too unfair. And that golden circlet? The worst.\nIf none of that had ever happened, that would've been perfect. It all boiled down to one question: Why?\nWhy couldn't he be the Great Sage? Why did he have to follow the grown-ups' rules? Why couldn't he stay free forever?\nSo what if the Five-Finger Mountain blocked his way? He wanted to see everything in this world—and nothing, absolutely nothing, would ever gonna stop him.\nJust watch me. Shaw repeated those three words fiercely to himself.",
        music = "805_LX_Birthday_2024"
      }
    }
  },
  [92019] = {
    [4101] = {
      [1] = {
        extrastory_title = "Little Adventurer",
        beijing = "Bg/1911.png",
        sentence = [[
In the bustling Aerospace Exhibit of the Children's Science Museum, a small figure popped out from the exit of the "Interstellar Voyage" tunnel. He dashed back toward the rest area, cheeks flushed with excitement.

"Mom! I'm back! I nailed it again!" Gavin puffed up his chest like a little hero, though his eyes couldn't resist sneaking one more glance at the entrance queue.

Wardia let out a soft chuckle and wiped the sweat from his brow, half amused, half exasperated. "Still wanna go again, huh?"
"Can I?"
"Of course. It's your big day. You can do whatever you want. Go ahead, I'll wait right here."
"Yay!"]],
        music = "52_Daily03"
      },
      [2] = {
        extrastory_title = "Little Adventurer",
        beijing = "Bg/1911.png",
        sentence = "Gavin took off once more toward the glimmering archway of the \"Voyage Capsule.\" As he neared the front of the line, he stood on tiptoe, waving back at his mom with all the enthusiasm in his little body.\n\nThe lights in the rest area glowed warm and inviting, feeling almost like the living room back at home. Gavin's mother waved back gently, as though she was sending him off into the stars and waiting to welcome him home at the same time.\n\n\"Warning—turbulence ahead! All interstellar squad members, please remain calm and continue your mission!\" The tunnel shimmered with swirling nebulae, and the booming voice echoed familiarly in Gavin's ears.",
        music = "52_Daily03"
      },
      [3] = {
        extrastory_title = "Little Adventurer",
        beijing = "Bg/1911.png",
        sentence = [[
The last time, he had gone left, where he was swept into a planetary battle, fought valiantly, and even forged an alliance with aliens to safeguard the galaxy. Another time, he took the center path and arrived in a sea of stars, where he'd caught a glimpse of a space station from afar.

What adventure awaited him this time?

Heart pounding, he chose a path he hadn't taken before. Gripping the handrails like a proper space cadet, he followed the queue deeper into the "cosmos."]],
        music = "52_Daily03"
      },
      [4] = {
        extrastory_title = "Little Adventurer",
        beijing = "Bg/1911.png",
        sentence = [[
The soundtrack softened into an airy melody. The tunnel lit up with vibrant hues, and the ceiling above unfurled like a theater dome. Rows of dazzling, laser-petaled flowers bloomed on both sides. Up ahead stood metallic trees, their limbs heavy with clear, plastic fruits.

"Whoa!!" Gavin's eyes widened, echoing the chorus of gasps from the kids around him.
"Congratulations, explorers! You've discovered a planet with signs of life. These plants are unlike anything on Earth. Please step up to the scanner, press the red button, and transmit the photos you took back to Earth."
"Did you know plants on Earth use sunlight to make food through something called photosynthesis?"]],
        music = "409_BQ_Birthday_2024"
      },
      [5] = {
        extrastory_title = "Little Adventurer",
        beijing = "Bg/1911.png",
        sentence = "Gavin snapped a picture and pressed the button. As the narration continued, the artificial sunlight intensified. The \"flowers\" reacted with animated rustles, rising just a bit taller as their mechanical stems creaked cheerfully. Knowledge once confined to books was now dancing before his very eyes.\n\nHe reached out, fingers hovering above a glistening \"space flower.\" They were unlike any real flower he'd ever seen—beautiful, bizarre, and strangely lovable. Could they survive on Earth?\n\nWouldn't it be amazing if he could bring one home?",
        music = "409_BQ_Birthday_2024"
      },
      [6] = {
        extrastory_title = "Little Adventurer",
        beijing = "Bg/1911.png",
        sentence = "But that wistful thought soon gave way to the excitement of what lay ahead. The next journey was calling—and with it, more wonder waiting to be discovered.\n\nOnce again, he returned to the rest area. This time, awaiting him, aside from his mom, was a steaming-hot \"Interstellar Explorer\" combo meal from the museum. Wrapped in packaging shaped like rockets and constellations, even the simplest snacks and drinks felt as if they'd been touched by the magic of space.\n\nHe took a big bite of the sausage, his words tumbling out fast as he eagerly recounted his adventures.",
        music = "409_BQ_Birthday_2024"
      },
      [7] = {
        extrastory_title = "Little Adventurer",
        beijing = "Bg/1911.png",
        sentence = [[
"Mom! I made friends with the aliens from the planet Kutata! I helped them fight off bad guys, and I even found a bunch of new planets!"

"Wow, look at you, little hero. So, what do these Kutata aliens look like?" She chuckled, wiping a bit of sauce from his mouth and nudging his water bottle closer.

"They're kinda squishy, like jelly! And they come in all sorts of colors. Oh! And they told me their planet's gravity is different from ours. The announcer said gravity on Mars is only... uh, 0.38 times Earth's!" His eyes sparkled, hands waving in the air as if sketching the cosmos.

"And I saw these weird flowers too, super shiny ones!"]],
        music = "409_BQ_Birthday_2024"
      },
      [8] = {
        extrastory_title = "Little Adventurer",
        beijing = "Bg/1911.png",
        sentence = [[
Hand in hand, he dragged his mom from one exhibit to the next, his enthusiasm never faltering. That night, when it came time to blow out the candles on his birthday cake, images of starships and space colonies still danced vividly behind his eyes.

He chewed thoughtfully on a sweet bite of cake, then looked up, face solemn with a new kind of resolve. "Mom... I wanna be a Galactic Ranger when I grow up."

"Oh? You don't want to be a police officer anymore?"

"If I'm a Galactic Ranger, I can protect the whole universe!" He said the new catchphrase he learned with pride, nodding with determination. "I'll keep the galaxy safe!"]],
        music = "409_BQ_Birthday_2024"
      },
      [9] = {
        extrastory_title = "Little Adventurer",
        beijing = "Bg/1911.png",
        sentence = "A flicker of doubt crossed his small face. What if changing your wish meant it wouldn't come true? But the warmth in his mother's voice swept away all the uncertainty. \"Whatever you want to be, I'll be cheering you on. Just promise me one thing—stay safe, no matter what.\"\n\n\"Of course!\" His reply was firm, louder than ever before. \"Even if I'm busy saving the galaxy, I'll still come home on time!\"\n\nWardia laughed, scooping him up into her arms, pressing a kiss to his messy hair. \"Deal. But you better tell me all about the cool stuff you see out there.\"\n \"The universe is vast and full of wonders. If you love it, keep reaching higher, and farther.\"",
        music = "409_BQ_Birthday_2024"
      }
    }
  },
  [92020] = {
